private fun version(file: File, project: String): Version = Version(
    file = file,
    // The name carries the composite sort key (millisecond * TICKS + a
    // per-process counter); dividing it back out gives the snapshot time
    // that the history dialog shows. Fall back to the file's own mtime when
    // the name is unrecognisable, so a stray file still has a sane label.
    stamp = file.name.substringBefore("__").toLongOrNull()?.div(STAMP_TICKS)
        ?: file.lastModified(),
    size = file.length(),
    project = project,
)

private fun stamp(): String = String.format(
    // millisecond << counter: two snapshots in the same millisecond (e.g. a
    // restore() snapshoting the pre-restore content) must not collide, or
    // the copy is silently dropped and "restore is undoable" breaks.
    "%017d", System.currentTimeMillis() * STAMP_TICKS + counter.incrementAndGet() % STAMP_TICKS,
)

private val counter = AtomicLong()

companion object {
    /** Room for the per-millisecond counter inside the composite sort key. */
    private const val STAMP_TICKS = 10_000L

