import java.io.File

enum class RuntimeKind(val id: String, val label: String) {
    PYTHON("python", "Python"),
    NODE("node", "Node"),
    NPX("npx", "npx"),
    ;

    companion object {
        fun from(id: String): RuntimeKind? = entries.firstOrNull { it.id == id }
    }
}

/**
 * A single execution. [target] is a script path for PYTHON/NODE and a package
 * specifier for NPX; [args] are the arguments after the script name.
 */
data class ExecRequest(
    val kind: RuntimeKind,
    val target: String,
    val args: List<String> = emptyList(),
    val cwd: File? = null,
    val stdin: String? = null,
)

data class ExecResult(
    val exitCode: Int,
    val stdout: String,
    val stderr: String,
    val durationMs: Long,
    val truncated: Boolean = false,
) {
    val isSuccess: Boolean get() = exitCode == 0
}

enum class OutputStream { STDOUT, STDERR }

/** Called from the runtime's worker thread; implementations must not block. */
interface OutputListener {
    fun onOutput(stream: OutputStream, text: String) {}
    fun onFinished(result: ExecResult) {}
    fun onFailed(error: Throwable) {}
}

interface ExecutionHandle {
    val isRunning: Boolean
    fun cancel()
}

/** One language runtime inside the app. */
interface ScriptRuntime {
    val kind: RuntimeKind
    val version: String
    fun isAvailable(): Boolean
    fun execute(request: ExecRequest, listener: OutputListener): ExecutionHandle
}

/**
 * A [ScriptRuntime] that can also run to completion synchronously. Used by the
 * agent shell and by npx, which have no coroutines/callbacks. Both the Rhino
 * fallback ([dev.pocketrun.runtime.js.JsRuntime]) and native Node implement it.
 */
interface SyncScriptRuntime : ScriptRuntime {
    fun executeSync(request: ExecRequest, timeoutMs: Long): ExecResult
}

package dev.pocketrun.runtime

import java.io.File
import java.io.IOException
import java.io.RandomAccessFile
import java.nio.ByteBuffer
import java.nio.CharBuffer
import java.nio.charset.CodingErrorAction
import java.nio.charset.StandardCharsets
import java.util.concurrent.atomic.AtomicBoolean

/**
 * Follows a file that another thread is appending to and reports the growth as
 * text. Python and the JS engine both write run output this way: a pipe would
 * let a slow reader block the interpreter, and a file also keeps the output if
 * the UI dies mid-run.
 */
class OutputTailer(
    private val file: File,
    private val stream: OutputStream,
    private val listener: OutputListener,
    private val stopped: AtomicBoolean,
    private val onDrained: () -> Unit,
) : Thread("pocketrun-tail-${stream.name.lowercase()}") {

    private var offset: Long = 0
    private val pending = StringBuilder()
    private val decodeBuffer = CharBuffer.allocate(1024)
    private val decoder = StandardCharsets.UTF_8.newDecoder()
        .onMalformedInput(CodingErrorAction.REPLACE)
        .onUnmappableCharacter(CodingErrorAction.REPLACE)

    /**
     * Bytes at the end of the last read that could not be decoded yet. The
     * decoder never consumes a partial multi-byte character; it leaves it in
     * the input buffer, and we have to hand it back with the next chunk.
     */
    private var undecoded = ByteArray(0)

    init {
        isDaemon = true
    }

    override fun run() {
        try {
            while (!stopped.get()) {
                if (drain()) onDrained()
                sleep(40)
            }
            drain()
        } catch (_: InterruptedException) {
            Thread.currentThread().interrupt()
        } catch (_: IOException) {
            // The run directory was deleted mid-tail; stop following instead of
            // killing the thread with an uncaught exception.
        } catch (_: SecurityException) {
            // Same story with an unreadable file.
        } finally {
            finishDecoder()
            flushPartial()
            onDrained()
        }
    }

    private fun drain(): Boolean {
        if (!file.isFile) return false
        val length = file.length()
        if (length <= offset) return false
        var grew = false
        RandomAccessFile(file, "r").use { handle ->
            handle.seek(offset)
            val chunk = ByteArray((length - offset).coerceAtMost(64L * 1024L).toInt())
            val read = handle.read(chunk)
            if (read > 0) {
                offset += read
                decodeChunk(chunk, read)
                grew = true
            }
        }
        if (grew) emitCompleteLines()
        return grew
    }

    /**
     * Incremental UTF-8 decode. The one-shot `decode(ByteBuffer)` convenience
     * method resets the decoder, so a multi-byte character split across two
     * reads would come out as U+FFFD. The ByteBuffer/CharBuffer pair leaves
     * undecodable trailing bytes in the input buffer instead; we carry those
     * over to the next chunk, so Cyrillic or emoji never gets mangled at a
     * read boundary.
     */
    private fun decodeChunk(chunk: ByteArray, length: Int) {
        val input = if (undecoded.isEmpty()) {
            ByteBuffer.wrap(chunk, 0, length)
        } else {
            ByteBuffer.allocate(undecoded.size + length).apply {
                put(undecoded)
                put(chunk, 0, length)
                flip()
            }
        }
        while (input.hasRemaining()) {
            decodeBuffer.clear()
            val result = decoder.decode(input, decodeBuffer, false)
            decodeBuffer.flip()
            if (decodeBuffer.hasRemaining()) pending.append(decodeBuffer)
            if (result.isUnderflow()) break
            // OVERFLOW: the buffer filled with input still left; go around again.
        }
        undecoded = if (input.hasRemaining()) {
            val tail = ByteArray(input.remaining())
            input.get(tail)
            tail
        } else {
            ByteArray(0)
        }
    }

    /** Decodes whatever an incomplete trailing character turns into after REPLACE. */
    private fun finishDecoder() {
        if (undecoded.isEmpty()) return
        decodeBuffer.clear()
        decoder.decode(ByteBuffer.wrap(undecoded), decodeBuffer, true)
        decodeBuffer.flip()
        if (decodeBuffer.hasRemaining()) pending.append(decodeBuffer)
        undecoded = ByteArray(0)
    }

    private fun emitCompleteLines() {
        var newline = pending.indexOf("\n")
        while (newline >= 0) {
            val line = pending.substring(0, newline).removeSuffix("\r")
            pending.delete(0, newline + 1)
            listener.onOutput(stream, line + "\n")
            newline = pending.indexOf("\n")
        }
        // A single very long line is flushed early so the UI keeps updating.
        if (pending.length > 32 * 1024) flushPartial()
    }

    private fun flushPartial() {
        if (pending.isEmpty()) return
        listener.onOutput(stream, pending.toString())
        pending.setLength(0)
    }
}

package dev.pocketrun.runtime.js

import android.util.Log
import dev.pocketrun.core.SystemInfo
import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.ExecRequest
import dev.pocketrun.runtime.ExecResult
import dev.pocketrun.runtime.ExecutionHandle
import dev.pocketrun.runtime.OutputListener
import dev.pocketrun.runtime.OutputTailer
import dev.pocketrun.runtime.OutputStream
import dev.pocketrun.runtime.RuntimeKind
import dev.pocketrun.runtime.SyncScriptRuntime
import org.mozilla.javascript.BaseFunction
import org.mozilla.javascript.Context
import org.mozilla.javascript.Function
import org.mozilla.javascript.RhinoException
import org.mozilla.javascript.Scriptable
import org.mozilla.javascript.ScriptableObject
import org.mozilla.javascript.Undefined
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.io.FileOutputStream
import java.io.OutputStreamWriter
import java.net.HttpURLConnection
import java.net.URL
import java.util.UUID
import java.util.concurrent.Callable
import java.util.concurrent.ExecutionException
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.Future
import java.util.concurrent.TimeUnit
import java.util.concurrent.TimeoutException
import java.util.concurrent.atomic.AtomicBoolean

/**
 * The JavaScript runtime: Rhino evaluating [bootSource] (node/boot.js from the
 * APK assets) into a fresh safe scope per run, plus the event loop the boot
 * script drives through its `__pr*` hooks.
 *
 * The bridge contract lives at the top of boot.js; this class is its only
 * implementation. Scripts reach the outside world only through the bridge, and
 * every filesystem call is contained inside the workspace root by [Workspace.resolve].
 *
 * Runs are serialized on one worker thread (Rhino contexts are not shareable);
 * output is streamed through per-run log files exactly like PythonRuntime.
 */
class JsRuntime(
    private val bootSource: String,
    private val workspace: Workspace,
    private val maxRunMs: Long = 10 * 60_000L,
) : SyncScriptRuntime {

    companion object {
        private const val TAG = "JsRuntime"
        private const val MAX_CAPTURE = 256 * 1024
        private const val TAILER_JOIN_MS = 2_000L
        private const val MAX_READ = 16 * 1024 * 1024
        private const val MAX_HTTP_BODY = 4 * 1024 * 1024
        const val VERSION = "Rhino 1.8.1 (ES6,interpreted)"
    }

    override val kind: RuntimeKind = RuntimeKind.NODE
    override val version: String = VERSION
    override fun isAvailable(): Boolean = true

    private val executor: ExecutorService = Executors.newSingleThreadExecutor { runnable ->
        Thread(runnable, "pocketrun-js-run").apply { isDaemon = true }
    }

    /** Per-run mutable state, confined to the worker thread while a run is live. */
    private class RunState(
        val request: ExecRequest,
        val outFile: File,
        val errFile: File,
        defaultRoot: File,
    ) {
        var cwd: File = request.cwd?.takeIf { it.isDirectory } ?: defaultRoot
        val stdout = Capture()
        val stderr = Capture()

        val outWriter by lazy { OutputStreamWriter(FileOutputStream(outFile, true), Charsets.UTF_8) }
        val errWriter by lazy { OutputStreamWriter(FileOutputStream(errFile, true), Charsets.UTF_8) }
    }

    override fun execute(request: ExecRequest, listener: OutputListener): ExecutionHandle {
        val cancelled = AtomicBoolean(false)
        val running = AtomicBoolean(true)
        val startedAt = System.currentTimeMillis()
        val runDir = File(workspace.cache, "runs/${UUID.randomUUID()}").apply { mkdirs() }
        val state = RunState(request, File(runDir, "out.log"), File(runDir, "err.log"), workspace.root)
        val stopped = AtomicBoolean(false)

        val outTailer = OutputTailer(state.outFile, OutputStream.STDOUT, CaptureListener(listener, state.stdout), stopped) {}
        val errTailer = OutputTailer(state.errFile, OutputStream.STDERR, CaptureListener(listener, state.stderr), stopped) {}
        outTailer.start()
        errTailer.start()

        val future: Future<Int> = executor.submit(Callable {
            try {
                val exitCode = runLocked(state, cancelled)
                stopped.set(true)
                stopTailers(outTailer, errTailer)
                listener.onFinished(
                    ExecResult(
                        exitCode = exitCode,
                        stdout = state.stdout.text(),
                        stderr = state.stderr.text(),
                        durationMs = System.currentTimeMillis() - startedAt,
                        truncated = state.stdout.truncated || state.stderr.truncated,
                    ),
                )
                exitCode
            } catch (t: Throwable) {
                stopped.set(true)
                stopTailers(outTailer, errTailer)
                listener.onFailed(t)
                1
            } finally {
                running.set(false)
                runDir.deleteRecursively()
            }
        })

        return object : ExecutionHandle {
            override val isRunning: Boolean get() = running.get() && !future.isDone
            override fun cancel() { cancelled.set(true) }
        }
    }

    /**
     * Runs [request] to completion (waiting for the worker) and returns the
     * result. On timeout the run is flagged cancelled and a 124 result is
     * returned. Used by the agent's run_node tool.
     */
    override fun executeSync(request: ExecRequest, timeoutMs: Long): ExecResult {
        val done = java.util.concurrent.CompletableFuture<ExecResult>()
        val handle = execute(request, object : OutputListener {
            override fun onFinished(result: ExecResult) { done.complete(result) }
            override fun onFailed(error: Throwable) { done.completeExceptionally(error) }
        })
        return try {
            done.get(timeoutMs, TimeUnit.MILLISECONDS)
        } catch (e: TimeoutException) {
            handle.cancel()
            ExecResult(124, "", "превышено время выполнения (${timeoutMs / 1000} с)", timeoutMs)
        } catch (e: ExecutionException) {
            ExecResult(1, "", e.cause?.message ?: e.message ?: "ошибка запуска", 0)
        }
    }

    // ---------------------------------------------------------------- engine

    private fun runLocked(state: RunState, cancelled: AtomicBoolean): Int {
        val cx = Context.enter()
        try {
            cx.languageVersion = Context.VERSION_ES6
            cx.optimizationLevel = -1 // no bytecode generation: required on Android
            val scope = cx.initSafeStandardObjects()
            installBridge(cx, scope, state)
            cx.evaluateString(scope, bootSource, "boot.js", 1, null)

            // Entry module resolves relative requires against its own directory.
            val target = state.request.target
            if (target.startsWith("/")) {
                val dir = target.substringBeforeLast('/', "")
                callGlobal(cx, scope, "__setMainDir") { arrayOf<Any?>(dir) }
            }

            var exitCode = try {
                val source = readMainSource(state.request)
                cx.evaluateString(scope, source, state.request.target, 1, null)
                0
            } catch (e: RhinoException) {
                state.errWriter.write(
                    "ERROR at line ${e.lineNumber()} in ${e.sourceName()}: ${e.details()}\n" +
                        e.getScriptStackTrace() + "\n",
                )
                state.errWriter.flush()
                1
            }

            // Event loop: driven by the boot script's hooks.
            val loopStart = System.currentTimeMillis()
            while (true) {
                if (System.currentTimeMillis() - loopStart > maxRunMs) {
                    if (exitCode == 0) exitCode = 124
                    state.errWriter.write("run timeout after ${maxRunMs / 1000}s\n"); state.errWriter.flush()
                    break
                }
                val ex = callGlobal(cx, scope, "__prExitCode") { arrayOfNulls(0) }
                if (ex != null && ex != Undefined.instance) {
                    exitCode = Context.toNumber(ex).toInt()
                    break
                }
                if (cancelled.get()) { exitCode = 130; break }
                val pending = Context.toNumber(callGlobal(cx, scope, "__prPending") { arrayOfNulls(0) })
                if (pending <= 0.0) break
                val next = Context.toNumber(callGlobal(cx, scope, "__prNextDue") { arrayOfNulls(0) })
                val now = System.currentTimeMillis()
                if (next > now + 1.0) {
                    try {
                        Thread.sleep((next - now).coerceAtMost(20.0).toLong())
                    } catch (e: InterruptedException) {
                        Thread.currentThread().interrupt()
                        if (exitCode == 0) exitCode = 130
                        break
                    }
                    continue
                }
                try {
                    callGlobal(cx, scope, "__prRunDue") { arrayOfNulls(0) }
                } catch (e: RhinoException) {
                    // boot.js already isolates per-callback failures; this is a last resort
                    state.errWriter.write("event loop error: ${e.details()}\n"); state.errWriter.flush()
                    if (exitCode == 0) exitCode = 1
                    break
                }
            }
            try {
                callGlobal(cx, scope, "__prOnExit") { arrayOfNulls(0) }
            } catch (_: Exception) { }
            state.outWriter.flush()
            state.errWriter.flush()
            return exitCode
        } finally {
            try { state.outWriter.flush(); state.errWriter.flush() } catch (_: Exception) {}
            Context.exit()
        }
    }

    /**
     * The script to evaluate, sandboxed: `require` is already gated by
     * [sandboxFile], and the entry point needs the same check — otherwise a
     * script outside the workspace (a path from a stale run, a package `bin`
     * pointing at `../../../shared_prefs/…`) would be evaluated as JavaScript.
     */
    private fun readMainSource(request: ExecRequest): String {
        val file = workspace.resolve(request.target, request.cwd ?: workspace.root)
            ?: throw IllegalStateException("путь вне рабочей папки отклонён: ${request.target}")
        if (!file.isFile) throw IllegalStateException("скрипт не найден: ${request.target}")
        // Bin scripts start with a shebang; Rhino has no '#' comments.
        return file.readText(Charsets.UTF_8).replace(Regex("^#![^\\n]*\\n?"), "")
    }

    private fun callGlobal(cx: Context, scope: Scriptable, name: String, args: () -> Array<Any?>): Any? {
        val fn = scope.get(name, scope)
        if (fn is Function) return fn.call(cx, scope, scope, args())
        return null
    }

    private fun stopTailers(outTailer: OutputTailer, errTailer: OutputTailer) {
        // The tailers watch log files that this thread just closed; give them a
        // moment to drain. (OutputTailer stops when the run dir disappears.)
        try { outTailer.join(TAILER_JOIN_MS) } catch (_: InterruptedException) {}
        try { errTailer.join(TAILER_JOIN_MS) } catch (_: InterruptedException) {}
    }

    // ---------------------------------------------------------------- bridge

    /**
     * Installs the `__pr` object with every function boot.js calls. Functions
     * are BaseFunction subclasses (NOT javaToJS): the safe scope must not see
     * arbitrary Java objects.
     */
    private fun installBridge(cx: Context, scope: Scriptable, state: RunState) {
        val bridge = cx.newObject(scope)
        ScriptableObject.putProperty(scope, "__pr", bridge)

        fun method(name: String, fn: (Array<Any?>) -> Any?) {
            ScriptableObject.putProperty(bridge, name, object : BaseFunction() {
                // NOTE: a Kotlin null here becomes JS null — boot.js checks
                // `=== null` for "no such file" and friends, so mapping null to
                // undefined would silently break those checks.
                override fun call(c: Context, s: Scriptable, thisObj: Scriptable, args: Array<Any?>?): Any? {
                    return fn(args ?: arrayOfNulls(0))
                }
            })
        }

        fun str(a: Array<Any?>, i: Int): String? = a.getOrNull(i)?.let { if (it === Undefined.instance) null else Context.toString(it) }

        method("root") { workspace.root.absolutePath }
        method("now") { System.currentTimeMillis().toDouble() }

        // Native process/OS facts for the boot.js os and process modules. The
        // static half is read once, the volatile half on every call.
        method("sysinfo") { systemInfoJson() }
        method("sysstat") { systemStatJson() }
        method("memoryUsage") { memoryUsageJson() }
        method("hrtime") { SystemInfo.hrtimeNanos().toDouble() }

        method("print") { a -> str(a, 0)?.let { writeOut(state, it) } }
        method("printErr") { a -> str(a, 0)?.let { writeErr(state, it) } }

        method("argv") {
            // Must be exactly Object[] for Context.newArray (see Rhino's checks).
            val list = buildList<Any?> {
                add("node")
                add(state.request.target)
                state.request.args.forEach { add(it) }
            }
            cx.newArray(scope, list.toTypedArray())
        }
        method("env") {
            val pairs = buildList<Any?> {
                add("HOME=${workspace.root.absolutePath}")
                add("PATH=/usr/local/bin:/usr/bin:/bin")
                add("LANG=C.UTF-8")
                add("NODE_ENV=production")
                add("TMPDIR=${File(workspace.cache, "tmp").apply { mkdirs() }.absolutePath}")
            }
            cx.newArray(scope, pairs.toTypedArray())
        }

        method("cwd") { state.cwd.absolutePath }
        method("chdir") { a ->
            val d = str(a, 0) ?: return@method false
            val resolved = workspace.resolve(d, state.cwd) ?: return@method false
            if (resolved.isDirectory) { state.cwd = resolved; true } else false
        }

        method("fsRead") { a ->
            val f = sandboxFile(str(a, 0)) ?: return@method null
            if (!f.isFile || f.length() > MAX_READ) null else f.readText(Charsets.UTF_8)
        }
        method("fsWrite") { a ->
            val f = sandboxFile(str(a, 0)) ?: return@method false
            try {
                f.parentFile?.mkdirs()
                f.writeText(str(a, 1) ?: "", Charsets.UTF_8)
                true
            } catch (t: Throwable) { false }
        }
        method("fsAppend") { a ->
            val f = sandboxFile(str(a, 0)) ?: return@method false
            try {
                f.parentFile?.mkdirs()
                f.appendText(str(a, 1) ?: "", Charsets.UTF_8)
                true
            } catch (t: Throwable) { false }
        }
        method("fsExists") { a -> sandboxFile(str(a, 0))?.exists() == true }
        method("fsIsDir") { a -> sandboxFile(str(a, 0))?.isDirectory == true }
        method("fsList") { a ->
            val f = sandboxFile(str(a, 0)) ?: return@method null
            if (!f.isDirectory) return@method null
            val names: Array<Any?> = f.list()?.sorted()?.map { it as Any? }?.toTypedArray()
                ?: arrayOfNulls<Any?>(0)
            cx.newArray(scope, names)
        }
        method("fsSize") { a ->
            val f = sandboxFile(str(a, 0))
            (f?.takeIf { it.isFile }?.length() ?: 0L).toDouble()
        }
        method("fsMtime") { a ->
            val f = sandboxFile(str(a, 0))
            (f?.takeIf { it.exists() }?.lastModified() ?: 0L).toDouble()
        }
        method("fsMkdir") { a ->
            val f = sandboxFile(str(a, 0)) ?: return@method false
            try { f.mkdirs(); true } catch (t: Throwable) { false }
        }
        method("fsDelete") { a ->
            val f = sandboxFile(str(a, 0)) ?: return@method false
            f.isFile && f.delete()
        }
        method("fsRename") { a ->
            val from = sandboxFile(str(a, 0)) ?: return@method false
            val to = sandboxFile(str(a, 1)) ?: return@method false
            try {
                to.parentFile?.mkdirs()
                from.renameTo(to)
            } catch (t: Throwable) { false }
        }

        method("http") { a ->
            val method = str(a, 0)?.uppercase() ?: "GET"
            val url = str(a, 1) ?: return@method null
            val headers = str(a, 2) ?: "{}"
            val body = str(a, 3)
            httpBridge(method, url, headers, body)
        }
    }

    /** Resolves an absolute path from boot.js against the sandbox; null if it escapes. */
    private fun sandboxFile(abs: String?): File? {
        if (abs == null) return null
        return workspace.resolve(abs)
    }

    private fun writeOut(state: RunState, text: String) {
        try {
            state.outWriter.write(text)
            state.outWriter.flush()
        } catch (t: Throwable) { Log.w(TAG, "stdout write failed", t) }
    }

    private fun writeErr(state: RunState, text: String) {
        try {
            state.errWriter.write(text)
            state.errWriter.flush()
        } catch (t: Throwable) { Log.w(TAG, "stderr write failed", t) }
    }

    /** Static hardware facts for `os.*` / `process.arch` / `process.pid`. */
    private fun systemInfoJson(): String {
        val cpus = JSONArray()
        for (cpu in SystemInfo.cpus()) {
            cpus.put(
                JSONObject()
                    .put("model", cpu.model)
                    .put("speed", cpu.speedMhz)
                    .put(
                        "times",
                        JSONObject()
                            .put("user", cpu.times.user)
                            .put("nice", cpu.times.nice)
                            .put("sys", cpu.times.sys)
                            .put("idle", cpu.times.idle)
                            .put("irq", cpu.times.irq),
                    ),
            )
        }
        val interfaces = JSONObject()
        for ((name, addresses) in SystemInfo.networkInterfaces()) {
            val list = JSONArray()
            for (address in addresses) {
                list.put(
                    JSONObject()
                        .put("address", address.address)
                        .put("family", address.family)
                        .put("mac", address.mac)
                        .put("internal", address.internal),
                )
            }
            interfaces.put(name, list)
        }
        return JSONObject()
            .put("arch", SystemInfo.arch)
            .put("abi", SystemInfo.abi)
            .put("release", SystemInfo.release)
            .put("hostname", SystemInfo.hostname)
            .put("totalmem", SystemInfo.totalMemory)
            .put("pid", SystemInfo.pid)
            .put("cpus", cpus)
            .put("networkInterfaces", interfaces)
            .toString()
    }

    /** Volatile counters that must not be cached: uptime, free memory, load. */
    private fun systemStatJson(): String {
        val load = JSONArray()
        SystemInfo.loadAverage.forEach { load.put(it) }
        return JSONObject()
            .put("uptime", SystemInfo.uptimeSeconds)
            .put("freemem", SystemInfo.freeMemory)
            .put("loadavg", load)
            .toString()
    }

    private fun memoryUsageJson(): String {
        val usage = SystemInfo.memoryUsage()
        return JSONObject()
            .put("rss", usage.rss)
            .put("heapTotal", usage.heapTotal)
            .put("heapUsed", usage.heapUsed)
            .put("external", usage.external)
            .put("arrayBuffers", usage.arrayBuffers)
            .toString()
    }

    /**
     * Synchronous http(s) for the boot.js `http`/`https` modules. Returns
     * `{"status":…,"headers":{…},"body":"…"}` as JSON text, or null on any
     * failure (boot.js turns that into a request 'error' event).
     */
    private fun httpBridge(method: String, url: String, headersJson: String, body: String?): String? {
        if (!url.startsWith("http://") && !url.startsWith("https://")) return null
        return try {
            val conn = URL(url).openConnection() as HttpURLConnection
            conn.requestMethod = method
            conn.connectTimeout = 15_000
            conn.readTimeout = 60_000
            conn.instanceFollowRedirects = true
            runCatching { JSONObject(headersJson) }.getOrNull()?.let { h ->
                for (key in h.keys()) conn.setRequestProperty(key, h.getString(key))
            }
            // An empty string means "no body" (boot.js passes '' for GET): setting
            // doOutput on a GET silently turns it into POST in HttpURLConnection.
            if (!body.isNullOrEmpty()) {
                conn.doOutput = true
                conn.setRequestProperty("Content-Length", body.toByteArray(Charsets.UTF_8).size.toString())
                conn.outputStream.use { it.write(body.toByteArray(Charsets.UTF_8)) }
            }
            val status = conn.responseCode
            val text = readCapped(conn, status)
            val headers = JSONObject()
            for ((k, v) in conn.headerFields) {
                if (k != null && !v.isNullOrEmpty()) headers.put(k, v.joinToString(", "))
            }
            JSONObject()
                .put("status", status)
                .put("headers", headers)
                .put("body", text)
                .toString()
        } catch (t: Throwable) {
            Log.w(TAG, "http $method $url failed: ${t.message}")
            null
        }
    }

    private fun readCapped(conn: HttpURLConnection, status: Int): String {
        val stream = if (status in 200..399) conn.inputStream else conn.errorStream ?: return ""
        return stream.use { input ->
            val out = java.io.ByteArrayOutputStream()
            val buf = ByteArray(16 * 1024)
            var total = 0
            while (total < MAX_HTTP_BODY) {
                val n = input.read(buf)
                if (n < 0) break
                out.write(buf, 0, n)
                total += n
            }
            out.toString("UTF-8")
        }
    }

    /** Forwards tailer output and keeps a capped copy for the final ExecResult. */
    private class CaptureListener(
        private val downstream: OutputListener,
        private val capture: Capture,
    ) : OutputListener {
        override fun onOutput(stream: OutputStream, text: String) {
            capture.append(text)
            downstream.onOutput(stream, text)
        }
    }

    private class Capture {
        private val builder = StringBuilder()
        var truncated = false
            private set

        fun append(text: String) {
            if (truncated) return
            val room = MAX_CAPTURE - builder.length
            if (room <= 0) { truncated = true; return }
            if (text.length <= room) builder.append(text) else {
                builder.append(text, 0, room)
                truncated = true
            }
        }

        fun text(): String = builder.toString()
    }
}

package dev.pocketrun.runtime.js

import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.ExecRequest
import dev.pocketrun.runtime.ExecResult
import dev.pocketrun.runtime.ExecutionHandle
import dev.pocketrun.runtime.OutputListener
import dev.pocketrun.runtime.OutputStream
import dev.pocketrun.runtime.RuntimeKind
import dev.pocketrun.runtime.SyncScriptRuntime
import java.io.File
import java.util.concurrent.CompletableFuture
import java.util.concurrent.ExecutionException
import java.util.concurrent.TimeUnit
import java.util.concurrent.TimeoutException
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference

/**
 * Native Node.js: nodejs-mobile ships real Node 18 as `libnode.so` but no
 * executable. The build packages a tiny launcher built on top of it as
 * `libnoderunner.so` in `jniLibs`, so Android extracts it to the app's
 * `nativeLibraryDir` where it can be exec'd. Each script becomes a real,
 * isolated, cancellable Node process.
 *
 * This is the primary NODE runtime on device; [JsRuntime] (Rhino) stays as the
 * fallback when the native launcher is missing (e.g. JVM unit tests).
 */
class NodeRuntime(
    nativeLibraryDir: File,
    private val workspace: Workspace,
    private val maxRunMs: Long = 10 * 60_000L,
) : SyncScriptRuntime {

    companion object {
        private const val MAX_CAPTURE = 256 * 1024
        const val VERSION = "Node.js 18.20.4 (nodejs-mobile)"
    }

    private val launcher = File(nativeLibraryDir, "libnoderunner.so")

    override val kind: RuntimeKind = RuntimeKind.NODE
    override val version: String = VERSION

    override fun isAvailable(): Boolean = launcher.isFile

    override fun execute(request: ExecRequest, listener: OutputListener): ExecutionHandle {
        val startedAt = System.currentTimeMillis()
        val running = AtomicBoolean(true)
        val cancelled = AtomicBoolean(false)
        val process = AtomicReference<Process?>(null)

        val thread = Thread({
            val out = StringBuilder()
            val err = StringBuilder()
            try {
                val p = launch(request)
                process.set(p)
                if (cancelled.get()) p.destroy()

                val outReader = Thread {
                    runCatching {
                        p.inputStream.bufferedReader(Charsets.UTF_8).useLines { lines ->
                            lines.forEach { line ->
                                appendCapped(out, line + "\n")
                                listener.onOutput(OutputStream.STDOUT, line + "\n")
                            }
                        }
                    }
                }
                val errReader = Thread {
                    runCatching {
                        p.errorStream.bufferedReader(Charsets.UTF_8).useLines { lines ->
                            lines.forEach { line ->
                                appendCapped(err, line + "\n")
                                listener.onOutput(OutputStream.STDERR, line + "\n")
                            }
                        }
                    }
                }
                outReader.start()
                errReader.start()

                request.stdin?.let { input ->
                    runCatching { p.outputStream.bufferedWriter(Charsets.UTF_8).use { it.write(input) } }
                }

                val exit = p.waitFor()
                outReader.join(2_000)
                errReader.join(2_000)
                if (!cancelled.get()) {
                    listener.onFinished(
                        ExecResult(
                            exitCode = exit,
                            stdout = out.toString(),
                            stderr = err.toString(),
                            durationMs = System.currentTimeMillis() - startedAt,
                            truncated = out.length >= MAX_CAPTURE || err.length >= MAX_CAPTURE,
                        ),
                    )
                }
            } catch (t: Throwable) {
                if (!cancelled.get()) listener.onFailed(t)
            } finally {
                running.set(false)
            }
        }, "pocketrun-node-run").apply { isDaemon = true }
        thread.start()

        return object : ExecutionHandle {
            override val isRunning: Boolean get() = running.get()
            override fun cancel() {
                cancelled.set(true)
                process.get()?.let { runCatching { it.destroy() } }
            }
        }
    }

    override fun executeSync(request: ExecRequest, timeoutMs: Long): ExecResult {
        val done = CompletableFuture<ExecResult>()
        val handle = execute(request, object : OutputListener {
            override fun onFinished(result: ExecResult) { done.complete(result) }
            override fun onFailed(error: Throwable) { done.completeExceptionally(error) }
        })
        return try {
            done.get(timeoutMs, TimeUnit.MILLISECONDS)
        } catch (e: TimeoutException) {
            handle.cancel()
            ExecResult(124, "", "превышено время выполнения (${timeoutMs / 1000} с)", timeoutMs)
        } catch (e: ExecutionException) {
            ExecResult(1, "", e.cause?.message ?: e.message ?: "ошибка запуска", 0)
        }
    }

    private fun launch(request: ExecRequest): Process {
        val script = File(request.target)
        check(script.isFile) { "скрипт не найден: ${request.target}" }
        val cwd = request.cwd?.takeIf { it.isDirectory } ?: workspace.root

        val command = ArrayList<String>(request.args.size + 2)
        command.add(launcher.absolutePath)
        command.add(script.absolutePath)
        command.addAll(request.args)

        val pb = ProcessBuilder(command)
        pb.directory(cwd)
        val env = pb.environment()
        env["LD_LIBRARY_PATH"] = launcher.parentFile?.absolutePath ?: ""
        env["HOME"] = workspace.root.absolutePath
        env["NODE_PATH"] = listOf(
            File(workspace.packages, "node_modules").absolutePath,
            workspace.packages.absolutePath,
        ).joinToString(":")
        return pb.start()
    }

    private fun appendCapped(sb: StringBuilder, text: String) {
        if (sb.length >= MAX_CAPTURE) return
        sb.append(text, 0, minOf(text.length, MAX_CAPTURE - sb.length))
    }
}

package dev.pocketrun.runtime.npm

import org.json.JSONObject
import java.io.File
import java.io.FileOutputStream
import java.io.InputStream
import java.net.HttpURLConnection
import java.net.URL
import java.net.URLEncoder
import java.security.MessageDigest
import java.util.Base64

/**
 * The slice of the npm registry HTTP API the app needs: package metadata and
 * tarball downloads. Works against registry.npmjs.org; the same endpoints are
 * served by any npm mirror (GPR, Verdaccio, …) by changing [baseUrl].
 *
 * A registry is a code source: whoever answers it chooses the JavaScript the
 * app evaluates. Two things are therefore checked on every tarball — the digest
 * the metadata promised, and that the download really comes from the registry
 * the metadata came from. Metadata without a digest is refused, exactly like
 * npm does.
 */
class NpmRegistry(private val baseUrl: String = "https://registry.npmjs.org/") {

    class RegistryException(message: String) : Exception(message)

    /** Full metadata document for [name]; scoped names are URL-encoded. */
    fun metadata(name: String): JSONObject {
        val encoded = URLEncoder.encode(name, "UTF-8")
        val text = http(baseUrl + encoded) { conn ->
            conn.setRequestProperty("Accept", "application/json")
        }
        return try {
            JSONObject(text)
        } catch (t: Throwable) {
            throw RegistryException("registry вернул не-JSON ответ для $name")
        }
    }

    /**
     * Downloads the tarball at [url] into [dest] and proves it is the one the
     * metadata described.
     *
     * @param integrity the `dist.integrity` value (`sha512-<base64>`, possibly
     *   several space-separated digests). Required: a packument without it
     *   cannot be trusted to be the real package.
     */
    fun downloadTarball(url: String, dest: File, integrity: String?) {
        requireTrusted(url)
        val expected = requireIntegrity(integrity, url)
        http(url, dest)
        val actual = digestOf(dest, expected.algorithm)
        if (actual != expected.b64) {
            // Never leave a tarball that failed its check on disk: the caller
            // would happily extract it.
            dest.delete()
            val detail = expected.algorithms.joinToString(", ")
            throw RegistryException(
                "несовпадение контрольной суммы tarball (ожидалась $detail, получено " +
                    "${actual.take(12)}…) — пакет отклонён",
            )
        }
    }

    // ------------------------------------------------------------- digests

    /** One expected digest: the algorithm and the base64 it must equal. */
    private data class Expected(val algorithm: String, val b64: String, val algorithms: List<String>)

    private fun requireIntegrity(integrity: String?, url: String): Expected {
        val digests = integrity?.split(' ', '\t')?.map { it.trim() }?.filter { it.isNotEmpty() }.orEmpty()
        val parsed = digests.mapNotNull { parseDigest(it) }
        if (parsed.isEmpty()) {
            throw RegistryException(
                "в метаданных нет integrity для ${url.take(120)} — пакет без контрольной суммы не ставится",
            )
        }
        // The strongest digest is the one that is checked; npm does the same.
        val strongest = parsed.maxBy { it.first.length }
        return Expected(strongest.first, strongest.second, parsed.map { it.first }.distinct())
    }

    private fun parseDigest(value: String): Pair<String, String>? {
        val dash = value.indexOf('-')
        if (dash <= 0) return null
        val algorithm = value.substring(0, dash).lowercase()
        if (algorithm !in SUPPORTED) return null
        val b64 = value.substring(dash + 1)
        return runCatching { Base64.getDecoder().decode(b64) }.map { algorithm to b64 }.getOrNull()
    }

    private fun digestOf(file: File, algorithm: String): String {
        val digest = MessageDigest.getInstance(algorithm)
        file.inputStream().use { input ->
            val buf = ByteArray(64 * 1024)
            while (true) {
                val n = input.read(buf)
                if (n < 0) break
                digest.update(buf, 0, n)
            }
        }
        return Base64.getEncoder().encodeToString(digest.digest())
    }

    /**
     * A tarball must be https and must live on the registry the metadata came
     * from — otherwise a compromised packument can point the app at an
     * arbitrary host and the integrity check would only prove that *that* host
     * serves what it said.
     */
    private fun requireTrusted(url: String) {
        val parsed = runCatching { URL(url) }.getOrElse {
            throw RegistryException("некорректный tarball URL: ${url.take(120)}")
        }
        if (parsed.protocol != "https") {
            throw RegistryException("tarball должен скачиваться по https, а не ${parsed.protocol}")
        }
        val registry = runCatching { URL(baseUrl).host }.getOrElse { "" }
        val host = parsed.host.lowercase()
        val allowed = registry.lowercase()
        if (allowed.isNotEmpty() && host != allowed && !host.endsWith(".$allowed")) {
            throw RegistryException(
                "tarball лежит на $host, а метаданные пришли с $allowed — пакет отклонён",
            )
        }
    }

    // ---------------------------------------------------------------- http

    private inline fun http(url: String, prepare: (HttpURLConnection) -> Unit = {}): String {
        val conn = open(url)
        prepare(conn)
        val status = conn.responseCode
        val text = streamText(conn, status)
        if (status !in 200..299) {
            throw RegistryException("HTTP $status для ${url.take(120)}: ${text.take(200)}")
        }
        return text
    }

    private fun http(url: String, dest: File) {
        val conn = open(url)
        val status = conn.responseCode
        if (status !in 200..299) {
            val text = streamText(conn, status)
            throw RegistryException("HTTP $status для ${url.take(120)}: ${text.take(200)}")
        }
        copy(conn.inputStream, dest)
    }

    private fun copy(input: InputStream, dest: File) {
        FileOutputStream(dest).use { out ->
            val buf = ByteArray(64 * 1024)
            while (true) {
                val n = input.read(buf)
                if (n < 0) break
                out.write(buf, 0, n)
            }
        }
    }

    private fun open(url: String): HttpURLConnection {
        if (!url.startsWith("https://") && !url.startsWith("http://")) {
            throw RegistryException("поддерживаются только http(s) URL")
        }
        val conn = URL(url).openConnection() as HttpURLConnection
        conn.connectTimeout = 15_000
        conn.readTimeout = 120_000
        conn.instanceFollowRedirects = true
        // npmjs.org rejects requests without a user agent.
        conn.setRequestProperty("User-Agent", "pocketrun-npm/1.2 (Rhino)")
        return conn
    }

    private fun streamText(conn: HttpURLConnection, status: Int): String {
        val stream = if (status in 200..299) conn.inputStream else conn.errorStream
        if (stream == null) return ""
        // Success bodies (package metadata) can be megabytes; only error text is capped.
        return if (status in 200..299) {
            stream.bufferedReader(Charsets.UTF_8).use { it.readText() }
        } else {
            stream.bufferedReader(Charsets.UTF_8).use { it.readText().take(8_192) }
        }
    }

    companion object {
        private val SUPPORTED = setOf("sha512", "sha384", "sha256", "sha1")
    }
}

package dev.pocketrun.runtime.npm

import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.ExecRequest
import dev.pocketrun.runtime.ExecResult
import dev.pocketrun.runtime.ExecutionHandle
import dev.pocketrun.runtime.OutputListener
import dev.pocketrun.runtime.OutputStream
import dev.pocketrun.runtime.RuntimeKind
import dev.pocketrun.runtime.SyncScriptRuntime
import org.json.JSONObject
import java.io.File
import java.util.UUID
import java.util.concurrent.CountDownLatch
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference

/**
 * npm/npx for pure-JS packages: `install` downloads a registry tarball into
 * `workspace/packages/<name>` (dependencies hoisted there too; conflicting
 * versions nest under `packages/<parent>/node_modules/<dep>`, which is exactly
 * where boot.js looks while walking up), and `run` executes the package `bin`
 * through [JsRuntime] with the caller's working directory.
 *
 * Real `npx <pkg>` semantics, minus native addons and postinstall scripts —
 * those cannot work inside the sandbox and are skipped.
 */
class NpxRuntime(
    private val js: SyncScriptRuntime,
    private val workspace: Workspace,
    private val registry: NpmRegistry = NpmRegistry(),
) {

    companion object {
        private const val MAX_PACKAGES = 40
        private const val MAX_DEPTH = 4
        private const val DEFAULT_TIMEOUT_MS = 180_000L

        /** `name`, `name@version`, `@scope/name`, `@scope/name@version`. */
        fun parseSpec(raw: String): PackageSpec? {
            val s = raw.trim()
            if (s.isEmpty()) return null
            val at = if (s.startsWith("@")) s.indexOf('@', 1) else s.indexOf('@')
            val name = if (at < 0) s else s.substring(0, at)
            val version = if (at < 0) null else s.substring(at + 1).trim().takeIf { it.isNotEmpty() }
            if (!Regex("^[a-zA-Z0-9@][a-zA-Z0-9@/._-]*$").matches(name)) return null
            if (name.count { it == '/' } > 1) return null
            if (name.startsWith("@") && name.indexOf('/', 1) < 0) return null
            return PackageSpec(name, version)
        }

        /** `pkg arg1 arg2` → spec + args (whitespace-separated, quotes respected). */
        fun parseCommandLine(line: String): Pair<PackageSpec, List<String>>? {
            val tokens = tokenize(line)
            val spec = tokens.firstOrNull()?.let { parseSpec(it) } ?: return null
            return spec to tokens.drop(1)
        }

        private fun tokenize(line: String): List<String> {
            val out = mutableListOf<String>()
            val cur = StringBuilder()
            var quote: Char? = null
            for (ch in line.trim()) {
                when {
                    quote != null && ch == quote -> quote = null
                    quote != null -> cur.append(ch)
                    ch == '"' || ch == '\'' -> quote = ch
                    ch.isWhitespace() -> { if (cur.isNotEmpty()) { out += cur.toString(); cur.clear() } }
                    else -> cur.append(ch)
                }
            }
            if (cur.isNotEmpty()) out += cur.toString()
            return out
        }
    }

    data class PackageSpec(val name: String, val version: String?)

    private val executor: ExecutorService = Executors.newSingleThreadExecutor { runnable ->
        Thread(runnable, "pocketrun-npx").apply { isDaemon = true }
    }

    /** Top-level install location for a package name. */
    fun packageDir(name: String): File = File(workspace.packages, name)

    fun installedPackages(): List<Pair<String, String>> =
        workspace.packages.listFiles { f -> f.isDirectory && File(f, "package.json").isFile }
            .orEmpty()
            .mapNotNull { dir ->
                val name = readName(File(dir, "package.json")) ?: return@mapNotNull null
                name to readVersion(File(dir, "package.json")).orEmpty()
            }
            .sortedBy { it.first.lowercase() }

    // ---------------------------------------------------------------- execute

    fun execute(request: ExecRequest, listener: OutputListener): ExecutionHandle {
        check(request.kind == RuntimeKind.NPX) { "NpxRuntime expects NPX requests" }
        val running = AtomicBoolean(true)
        val cancelled = AtomicBoolean(false)
        val inner = AtomicReference<ExecutionHandle?>(null)
        val installLog = StringBuilder()

        fun log(line: String) {
            synchronized(installLog) { installLog.append(line).append('\n') }
            listener.onOutput(OutputStream.STDOUT, line + "\n")
        }

        executor.execute {
            try {
                val spec = parseSpec(request.target)
                    ?: throw IllegalArgumentException(
                        "не удалось разобрать пакет '${request.target}' — ожидается имя[@версия]",
                    )
                val pkgDir = install(spec, cancelled, ::log)
                val binPath = resolveBin(pkgDir, spec.name)
                    ?: throw IllegalStateException("у пакета ${spec.name} нет исполняемого файла (bin) — возможно, он не поддерживается в песочнице")
                log("▶ запускаю ${spec.name} (${binPath.relativeToOrNull(workspace.root)?.path ?: binPath.path})")

                val jsRequest = ExecRequest(
                    kind = RuntimeKind.NODE,
                    target = binPath.absolutePath,
                    args = request.args,
                    cwd = request.cwd ?: workspace.root,
                    stdin = request.stdin,
                )
                inner.set(
                    js.execute(jsRequest, object : OutputListener {
                        override fun onOutput(stream: OutputStream, text: String) {
                            listener.onOutput(stream, text)
                        }

                        override fun onFinished(result: ExecResult) {
                            val prefix = synchronized(installLog) { installLog.toString() }
                            running.set(false)
                            listener.onFinished(
                                result.copy(
                                    stdout = prefix + result.stdout,
                                    stderr = withSyntaxHint(result.stderr),
                                ),
                            )
                        }

                        override fun onFailed(error: Throwable) {
                            running.set(false)
                            listener.onFailed(error)
                        }
                    }),
                )
            } catch (t: Throwable) {
                running.set(false)
                listener.onFailed(t)
            }
        }

        return object : ExecutionHandle {
            override val isRunning: Boolean get() = running.get()
            override fun cancel() {
                cancelled.set(true)
                inner.get()?.cancel()
            }
        }
    }

    /** Blocking variant used by the agent's run_npx tool. */
    fun executeSync(request: ExecRequest, timeoutMs: Long = DEFAULT_TIMEOUT_MS): ExecResult {
        val latch = CountDownLatch(1)
        var result: ExecResult? = null
        var error: Throwable? = null
        val handle = execute(request, object : OutputListener {
            override fun onFinished(r: ExecResult) { result = r; latch.countDown() }
            override fun onFailed(e: Throwable) { error = e; latch.countDown() }
        })
        return if (latch.await(timeoutMs, TimeUnit.MILLISECONDS)) {
            result ?: ExecResult(1, "", error?.message ?: "ошибка запуска npx", 0)
        } else {
            handle.cancel()
            ExecResult(124, "", "превышено время выполнения npx (${timeoutMs / 1000} с)", timeoutMs)
        }
    }

    /**
     * Rhino understands a large ES6 subset but no class/async/import/for-of-const.
     * When a package fails on that, say so plainly instead of a bare parse error.
     */
    private fun withSyntaxHint(stderr: String): String {
        if (!stderr.contains("Cannot parse module")) return stderr
        return stderr + "\n" +
            "⚠ Пакет использует синтаксис, который встроенный JS-движок не понимает\n" +
            "  (class / async-await / import-export / spread). Часто помогает более старая\n" +
            "  версия пакета — например cowsay@1.4.0 вместо cowsay@latest.\n"
    }

    // ---------------------------------------------------------------- install

    /**
     * Makes sure [spec] is installed under packages/ and returns its directory.
     * Reuses an existing install when the version satisfies the spec.
     */
    @Synchronized
    fun install(
        spec: PackageSpec,
        cancelled: AtomicBoolean = AtomicBoolean(false),
        log: (String) -> Unit = {},
        budget: IntArray = intArrayOf(MAX_PACKAGES),
    ): File {
        if (cancelled.get()) throw IllegalStateException("установка отменена")
        val pkgDir = packageDir(spec.name)
        val existing = readVersion(manifestOf(pkgDir))
        if (existing != null && spec.version?.let { Semver.isSupportedRange(it) } != false &&
            (spec.version == null || Semver.satisfiesString(existing, spec.version))
        ) {
            log("• ${spec.name}@$existing уже установлен")
            return pkgDir
        }
        if (existing != null) pkgDir.deleteRecursively()
        if (--budget[0] < 0) throw IllegalStateException("слишком много пакетов (лимит $MAX_PACKAGES)")

        log("⬇ ${spec.name}${spec.version?.let { "@$it" } ?: ""}")
        val meta = registry.metadata(spec.name)
        val version = chooseVersion(meta, spec.version)
            ?: throw IllegalStateException("версия не найдена: ${spec.name}@${spec.version ?: "latest"}")
        val versionMeta = meta.optJSONObject("versions")?.optJSONObject(version)
            ?: throw IllegalStateException("в метаданных нет версии $version для ${spec.name}")
        log("  → ${spec.name}@$version")

        val tarball = versionMeta.optJSONObject("dist")?.optString("tarball")
        if (tarball.isNullOrEmpty()) throw IllegalStateException("у ${spec.name}@$version нет tarball")
        val tgz = File(workspace.cache, "tmp-${UUID.randomUUID()}.tgz")
        try {
            registry.downloadTarball(tarball, tgz, versionMeta.optJSONObject("dist")?.optString("integrity"))
            pkgDir.mkdirs()
            TarReader.extract(tgz, pkgDir, "package/")
        } finally {
            tgz.delete()
        }

        installDependencies(pkgDir, versionMeta, cancelled, log, budget)
        return pkgDir
    }

    private fun installDependencies(
        pkgDir: File,
        versionMeta: JSONObject,
        cancelled: AtomicBoolean,
        log: (String) -> Unit,
        budget: IntArray,
        depth: Int = 0,
    ) {
        if (depth >= MAX_DEPTH) return
        val deps = versionMeta.optJSONObject("dependencies") ?: return
        val names = deps.keys().asSequence().toList()
        for (dep in names) {
            if (cancelled.get()) throw IllegalStateException("установка отменена")
            val range = deps.optString(dep, "")
            if (!Semver.isSupportedRange(range)) {
                log("  ⚠ $dep пропущен (неподдерживаемый спецификатор: ${range.take(40)})")
                continue
            }
            val nested = File(pkgDir, "node_modules/$dep")
            val top = packageDir(dep)
            val nestedVer = readVersion(manifestOf(nested))
            if (nestedVer != null && Semver.satisfiesString(nestedVer, range)) continue
            val topVer = readVersion(manifestOf(top))
            if (topVer != null && Semver.satisfiesString(topVer, range)) {
                log("  • $dep@$topVer (уже установлен)")
                continue
            }
            // Hoist fresh deps to packages/; conflicting versions nest locally.
            val target = if (topVer != null) nested else top
            if (topVer != null) log("  ⚠ $dep: конфликт версий ($topVer не подходит под $range) — ставлю рядом")
            installInto(dep, range, target, cancelled, log, budget, depth)
        }
    }

    /** Installs [dep] exactly into [targetDir] (no reuse check for that dir). */
    private fun installInto(
        dep: String,
        range: String,
        targetDir: File,
        cancelled: AtomicBoolean,
        log: (String) -> Unit,
        budget: IntArray,
        depth: Int,
    ) {
        if (cancelled.get()) throw IllegalStateException("установка отменена")
        if (--budget[0] < 0) throw IllegalStateException("слишком много пакетов (лимит $MAX_PACKAGES)")
        log("  ⬇ $dep@$range")
        val meta = registry.metadata(dep)
        val version = chooseVersion(meta, range)
            ?: run {
                log("  ⚠ $dep: не найдена версия под $range — пропущен")
                return
            }
        val versionMeta = meta.optJSONObject("versions")?.optJSONObject(version) ?: return
        val tarball = versionMeta.optJSONObject("dist")?.optString("tarball") ?: return
        if (targetDir.exists()) targetDir.deleteRecursively()
        val tgz = File(workspace.cache, "tmp-${UUID.randomUUID()}.tgz")
        try {
            registry.downloadTarball(tarball, tgz, versionMeta.optJSONObject("dist")?.optString("integrity"))
            targetDir.mkdirs()
            TarReader.extract(tgz, targetDir, "package/")
        } finally {
            tgz.delete()
        }
        log("  ✓ $dep@$version")
        installDependencies(targetDir, versionMeta, cancelled, log, budget, depth + 1)
    }

    fun uninstall(name: String): Boolean {
        val spec = parseSpec(name) ?: return false
        val dir = packageDir(spec.name)
        return dir.exists() && dir.deleteRecursively()
    }

    // ---------------------------------------------------------------- metadata

    private fun manifestOf(pkgDir: File): File = File(pkgDir, "package.json")

    private fun readManifest(f: File): JSONObject? =
        if (!f.isFile) null else runCatching { JSONObject(f.readText(Charsets.UTF_8)) }.getOrNull()

    private fun readVersion(manifest: File): String? = readManifest(manifest)?.optString("version")?.takeIf { it.isNotEmpty() }

    private fun readName(manifest: File): String? = readManifest(manifest)?.optString("name")?.takeIf { it.isNotEmpty() }

    /** Resolves the requested version (exact / range / dist-tag) from metadata. */
    internal fun chooseVersion(meta: JSONObject, requested: String?): String? {
        val versions = meta.optJSONObject("versions") ?: return null
        if (requested == null || requested == "latest" || requested == "*") {
            val tag = meta.optJSONObject("dist-tags")?.optString("latest")?.takeIf { it.isNotEmpty() }
            if (tag != null && versions.has(tag)) return tag
            return versions.keys().asSequence()
                .filter { Semver.parse(it) != null }
                .maxWithOrNull { a, b -> Semver.compare(Semver.parse(a)!!, Semver.parse(b)!!) }
        }
        if (Semver.parse(requested) != null && versions.has(requested)) return requested
        val tag = meta.optJSONObject("dist-tags")?.optString(requested)?.takeIf { it.isNotEmpty() }
        if (tag != null && versions.has(tag)) return tag
        var best: String? = null
        for (key in versions.keys()) {
            val v = Semver.parse(key) ?: continue
            if (!Semver.satisfies(v, requested)) continue
            if (best == null || Semver.compare(v, Semver.parse(best)!!) > 0) best = key
        }
        return best
    }

    /** Finds the executable of an installed package: its `bin` entry. */
    internal fun resolveBin(pkgDir: File, name: String): File? {
        val manifest = readManifest(manifestOf(pkgDir)) ?: return null
        val bin = manifest.opt("bin") ?: return null
        val rel = when (bin) {
            is String -> bin
            is JSONObject -> {
                val short = name.substringAfterLast('/')
                bin.optString(short).takeIf { it.isNotEmpty() }
                    ?: bin.keys().asSequence().firstOrNull()?.let { bin.getString(it) }
            }
            else -> return null
        } ?: return null
        // A manifest can point `bin` anywhere ("../../../../shared_prefs/…"),
        // so the resolved file has to be inside the sandbox before it is read
        // as JavaScript.
        val f = workspace.resolve(rel, pkgDir)?.takeIf { it.isFile } ?: return null
        return f
    }
}

