package dev.pocketrun.runtime.npm

import java.io.File
import java.io.FileInputStream
import java.util.zip.GZIPInputStream

/**
 * Minimal reader for the `.tgz` tarballs npm serves (ustar format, entries
 * rooted at `package/`). Enough for registry packages: regular files and
 * directories; symlinks and special entries are skipped, every extracted path
 * is forced to stay inside [destDir].
 */
object TarReader {

    private const val BLOCK = 512

    class TarFormatException(message: String) : Exception(message)

    /** Extracts [tgz] into [destDir], stripping [stripPrefix] from entries. */
    fun extract(tgz: File, destDir: File, stripPrefix: String = "package/") {
        destDir.mkdirs()
        GZIPInputStream(FileInputStream(tgz)).use { gz ->
            val header = ByteArray(BLOCK)
            while (true) {
                if (!readFully(gz, header)) return
                if (header.all { it == 0.toByte() }) return // end-of-archive block
                var name = cstr(header, 0, 100)
                val size = octal(cstr(header, 124, 12))
                val typeFlag = if (header[156] == 0.toByte()) '0' else header[156].toInt().toChar()
                val prefix = cstr(header, 345, 155)
                if (prefix.isNotEmpty()) name = "$prefix/$name"
                if (name.isEmpty()) skipData(gz, size)

                val data = if (size > 0) readExact(gz, size) else ByteArray(0)

                val rel = strip(name, stripPrefix)
                when (typeFlag) {
                    '0' -> {
                        if (rel != null) {
                            val out = safeFile(destDir, rel)
                            if (out != null) {
                                out.parentFile?.mkdirs()
                                out.writeBytes(data)
                            }
                        }
                    }
                    '5' -> {
                        if (rel != null) safeFile(destDir, rel)?.mkdirs()
                    }
                    else -> Unit // 'x'/'g' pax headers, '2' symlinks, 'L' long names: consumed, ignored
                }
            }
        }
    }

    // ---------------------------------------------------------------- format

    private fun cstr(buf: ByteArray, offset: Int, len: Int): String {
        var end = offset
        val limit = minOf(offset + len, buf.size)
        while (end < limit && buf[end] != 0.toByte()) end++
        return String(buf, offset, end - offset, Charsets.UTF_8)
    }

    private fun octal(s: String): Long {
        val t = s.trim(' ', '\u0000')
        if (t.isEmpty()) return 0L
        return t.toLongOrNull(radix = 8) ?: throw TarFormatException("bad tar size field: '$s'")
    }

    private fun readFully(gz: GZIPInputStream, buf: ByteArray): Boolean {
        var done = 0
        while (done < buf.size) {
            val n = gz.read(buf, done, buf.size - done)
            if (n < 0) return false
            done += n
        }
        return true
    }

    private fun readExact(gz: GZIPInputStream, size: Long): ByteArray {
        val out = ByteArray(size.toInt())
        var done = 0
        while (done < out.size) {
            val n = gz.read(out, done, out.size - done)
            if (n < 0) throw TarFormatException("archive truncated inside entry data")
            done += n
        }
        // trailing padding to the next 512 boundary
        val pad = ((BLOCK - (size % BLOCK)) % BLOCK).toInt()
        if (pad > 0) skipData(gz, pad.toLong())
        return out
    }

    private fun skipData(gz: GZIPInputStream, size: Long) {
        var left = size
        val buf = ByteArray(BLOCK)
        while (left > 0) {
            val n = gz.read(buf, 0, minOf(buf.size.toLong(), left).toInt())
            if (n < 0) return
            left -= n
        }
    }

    // ---------------------------------------------------------------- paths

    private fun strip(name: String, prefix: String): String? {
        var n = name
        while (n.startsWith("./")) n = n.substring(2)
        if (n.isEmpty()) return null
        if (!prefix.isEmpty()) {
            if (!n.startsWith(prefix)) return null
            n = n.removePrefix(prefix)
        }
        while (n.startsWith("/")) return null // never absolute
        if (n.split('/').any { it == ".." }) return null
        if (n.isEmpty() || n == ".") return null
        return n
    }

    private fun safeFile(destDir: File, rel: String): File? {
        val target = File(destDir, rel).toPath().normalize()
        val root = destDir.toPath().normalize()
        if (target != root && !target.startsWith(root)) return null
        return target.toFile()
    }
}

package dev.pocketrun.runtime.python

import android.content.Context
import android.util.Log
import com.chaquo.python.Python
import com.chaquo.python.android.AndroidPlatform
import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.ExecRequest
import dev.pocketrun.runtime.ExecResult
import dev.pocketrun.runtime.ExecutionHandle
import dev.pocketrun.runtime.OutputListener
import dev.pocketrun.runtime.OutputTailer
import dev.pocketrun.runtime.OutputStream
import java.io.File
import java.util.UUID
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

/**
 * The CPython runtime. Chaquopy keeps one interpreter per process, so it is
 * started once from [initAsync] (about a second; never on the main thread) and
 * every [execute] afterwards reuses it.
 *
 * Scripts talk to the UI through files, not pipes: the Python bootstrap
 * (pocketrun.py) appends stdout/stderr to log files in the workspace cache and
 * two [OutputTailer]s stream them back as text.
 */
object PythonRuntime {

    private const val TAG = "PythonRuntime"
    private const val MAX_CAPTURE = 256 * 1024
    private const val TAILER_JOIN_MS = 2_000L

    private val lock = Any()

    @Volatile private var python: Python? = null
    @Volatile private var version: String? = null
    @Volatile private var workspace: Workspace? = null

    private val executor: ExecutorService = Executors.newSingleThreadExecutor { runnable ->
        Thread(runnable, "pocketrun-python-run").apply { isDaemon = true }
    }

    /** Starts CPython once. Safe to call again; returns immediately. */
    fun initAsync(context: Context) {
        if (python != null) return
        Thread({
            try {
                synchronized(lock) {
                    if (python == null) {
                        val appContext = context.applicationContext
                        Python.start(AndroidPlatform(appContext))
                        val py = Python.getInstance()
                        workspace = Workspace.from(appContext)
                        version = readVersion(py)
                        python = py
                        Log.i(TAG, "Python started ($version)")
                    }
                }
            } catch (t: Throwable) {
                Log.e(TAG, "Python failed to start", t)
            }
        }, "pocketrun-python-start").apply { isDaemon = true }.start()
    }

    fun isAvailable(): Boolean = python != null

    fun version(): String? = version

    private fun readVersion(py: Python): String? = try {
        py.getModule("pocketrun")
            .callAttr("interpreter_info")
            .get("version")
            .toString()
    } catch (t: Throwable) {
        Log.w(TAG, "interpreter_info failed", t)
        null
    }

    /**
     * Runs [request.target] with CPython. [listener.onOutput] arrives from the
     * tailer threads; [listener.onFinished] / [listener.onFailed] arrive from
     * the single run thread.
     *
     * The target and the working directory are resolved through
     * [Workspace.resolve] first, so a script can only ever be one of the files
     * inside the sandbox; the Python side repeats the check with an audit-hook
     * jail for everything the script does itself.
     *
     * Cancellation is cooperative: Chaquopy cannot interrupt a call, so
     * [ExecutionHandle.cancel] only raises a flag, and the result is reported
     * with exit code 130 (SIGINT) once the script returns on its own.
     */
    fun execute(request: ExecRequest, listener: OutputListener): ExecutionHandle {
        val py = python
        val stopped = AtomicBoolean(false)
        val cancelled = AtomicBoolean(false)
        val running = AtomicBoolean(true)
        if (py == null) {
            running.set(false)
            listener.onFailed(IllegalStateException("Python is not running (yet)"))
            return Handle(running, cancelled)
        }

        val sandbox = workspace
        if (sandbox == null) {
            running.set(false)
            listener.onFailed(IllegalStateException("Python is not running (yet)"))
            return Handle(running, cancelled)
        }
        val cwd = request.cwd?.let { sandbox.resolve(it.absolutePath) } ?: sandbox.root
        val target = sandbox.resolve(request.target, cwd)
        if (target == null) {
            running.set(false)
            listener.onFailed(IllegalArgumentException("путь вне рабочей папки отклонён: ${request.target}"))
            return Handle(running, cancelled)
        }

        val startedAt = System.currentTimeMillis()
        val runDir = File(sandbox.cache, "runs/${UUID.randomUUID()}").apply { mkdirs() }
        val outFile = File(runDir, "out.log")
        val errFile = File(runDir, "err.log")
        val stdout = Capture()
        val stderr = Capture()

        val outTailer = OutputTailer(outFile, OutputStream.STDOUT, CaptureListener(listener, stdout), stopped) {}
        val errTailer = OutputTailer(errFile, OutputStream.STDERR, CaptureListener(listener, stderr), stopped) {}
        outTailer.start()
        errTailer.start()

        executor.execute {
            try {
                val argsJson = org.json.JSONArray().apply { request.args.forEach { put(it) } }.toString()
                val exitCode = py.getModule("pocketrun").callAttr(
                    "run",
                    target.absolutePath,
                    argsJson,
                    request.stdin,
                    outFile.absolutePath,
                    errFile.absolutePath,
                    cwd.absolutePath,
                    sandbox.root.absolutePath,
                ).toInt()

                stopped.set(true)
                outTailer.join(TAILER_JOIN_MS)
                errTailer.join(TAILER_JOIN_MS)

                listener.onFinished(
                    ExecResult(
                        exitCode = if (cancelled.get()) 130 else exitCode,
                        stdout = stdout.text(),
                        stderr = stderr.text(),
                        durationMs = System.currentTimeMillis() - startedAt,
                        truncated = stdout.truncated || stderr.truncated,
                    ),
                )
            } catch (t: Throwable) {
                stopped.set(true)
                try {
                    outTailer.join(TAILER_JOIN_MS)
                    errTailer.join(TAILER_JOIN_MS)
                } catch (_: InterruptedException) {
                    Thread.currentThread().interrupt()
                }
                listener.onFailed(t)
            } finally {
                running.set(false)
                runDir.deleteRecursively()
            }
        }
        return Handle(running, cancelled)
    }

    /**
     * Runs [request] to completion (waiting for the worker) and returns the
     * result. On timeout the run is flagged cancelled and a 124 result is
     * returned. Used by the agent's run_python tool.
     */
    fun executeSync(request: ExecRequest, timeoutMs: Long): ExecResult {
        val done = java.util.concurrent.CompletableFuture<ExecResult>()
        val handle = execute(request, object : OutputListener {
            override fun onFinished(result: ExecResult) { done.complete(result) }
            override fun onFailed(error: Throwable) { done.completeExceptionally(error) }
        })
        return try {
            done.get(timeoutMs, java.util.concurrent.TimeUnit.MILLISECONDS)
        } catch (e: java.util.concurrent.TimeoutException) {
            handle.cancel()
            ExecResult(124, "", "превышено время выполнения (${timeoutMs / 1000} с)", timeoutMs)
        } catch (e: java.util.concurrent.ExecutionException) {
            ExecResult(1, "", e.cause?.message ?: e.message ?: "ошибка запуска", 0)
        }
    }

    /** Forwards tailer output and keeps a capped copy for the final ExecResult. */
    private class CaptureListener(
        private val downstream: OutputListener,
        private val capture: Capture,
    ) : OutputListener {
        override fun onOutput(stream: OutputStream, text: String) {
            capture.append(text)
            downstream.onOutput(stream, text)
        }
    }

    private class Capture {
        private val builder = StringBuilder()
        var truncated = false
            private set

        fun append(text: String) {
            if (truncated) return
            val room = MAX_CAPTURE - builder.length
            if (room <= 0) {
                truncated = true
                return
            }
            if (text.length <= room) {
                builder.append(text)
            } else {
                builder.append(text, 0, room)
                truncated = true
            }
        }

        fun text(): String = builder.toString()
    }

    private class Handle(
        private val running: AtomicBoolean,
        private val cancelled: AtomicBoolean,
    ) : ExecutionHandle {
        override val isRunning: Boolean get() = running.get()
        override fun cancel() = cancelled.set(true)
    }
}

package dev.pocketrun.runtime.shell

import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.ExecResult
import java.io.File
import java.util.concurrent.TimeUnit

/**
 * BusyBox 1.34.1 (meefik's Android build) packaged as `libbusybox.so` so
 * Android extracts it to `nativeLibraryDir`, where it can be exec'd. It gives
 * the mini-shell the long tail of real Unix utilities (sed, awk, sort, uniq,
 * cut, tr, tar, gzip, xargs, wget, diff, ...).
 *
 * Applets are real native processes. They run with their cwd inside the
 * workspace, but — unlike the sandboxed built-ins — they can touch anything the
 * app's UID can, so the workspace jail does not apply to them.
 */
class Busybox(
    nativeLibraryDir: File,
    private val workspace: Workspace,
    private val defaultTimeoutMs: Long = 120_000L,
) {

    companion object {
        private const val MAX_CAPTURE = 256 * 1024
        const val VERSION = "BusyBox 1.34.1"
    }

    private val binary = File(nativeLibraryDir, "libbusybox.so")

    /** Absolute path of the executable, for `which` output. */
    val binaryPath: String get() = binary.absolutePath

    @Volatile
    private var cachedApplets: Set<String>? = null

    fun isAvailable(): Boolean = binary.isFile

    /** Applet names from `busybox --list`; empty when the binary is missing. */
    fun applets(): Set<String> {
        cachedApplets?.let { return it }
        if (!isAvailable()) return emptySet()
        val listed = run(listOf("--list"), workspace.root, null, 15_000L)
        val set = listed.stdout.lineSequence()
            .map { it.trim() }
            .filter { it.isNotEmpty() }
            .toSet()
        cachedApplets = set
        return set
    }

    fun knowsApplet(name: String): Boolean = name in applets()

    /**
     * Runs `busybox <args...>` (args[0] is the applet). Returns 124 on timeout,
     * 127 when the binary is missing.
     */
    fun run(
        args: List<String>,
        cwd: File,
        stdin: String?,
        timeoutMs: Long = defaultTimeoutMs,
    ): ExecResult {
        if (!isAvailable()) return ExecResult(127, "", "busybox недоступен\n", 0)
        if (args.isEmpty()) return ExecResult(1, "", "busybox: нужен applet\n", 0)

        val startedAt = System.currentTimeMillis()
        val command = ArrayList<String>(args.size + 1)
        command.add(binary.absolutePath)
        command.addAll(args)

        val pb = ProcessBuilder(command)
        pb.directory(cwd.takeIf { it.isDirectory } ?: workspace.root)
        pb.environment()["HOME"] = workspace.root.absolutePath
        pb.environment()["LANG"] = "C.UTF-8"

        val proc = pb.start()
        val out = StringBuilder()
        val err = StringBuilder()

        val outReader = Thread {
            runCatching {
                proc.inputStream.bufferedReader(Charsets.UTF_8).useLines { lines ->
                    lines.forEach { appendCapped(out, it + "\n") }
                }
            }
        }
        val errReader = Thread {
            runCatching {
                proc.errorStream.bufferedReader(Charsets.UTF_8).useLines { lines ->
                    lines.forEach { appendCapped(err, it + "\n") }
                }
            }
        }
        outReader.start()
        errReader.start()
        try {
            proc.outputStream.bufferedWriter(Charsets.UTF_8).use { writer ->
                if (!stdin.isNullOrEmpty()) writer.write(stdin)
            }
        } catch (_: Exception) {
        }

        val finished = proc.waitFor(timeoutMs, TimeUnit.MILLISECONDS)
        if (!finished) {
            proc.destroyForcibly()
            proc.waitFor(2, TimeUnit.SECONDS)
            outReader.join(1_000)
            errReader.join(1_000)
            return ExecResult(
                124,
                out.toString(),
                (err.toString() + "превышено время выполнения busybox (${timeoutMs / 1000} с)\n"),
                System.currentTimeMillis() - startedAt,
                truncated = out.length >= MAX_CAPTURE || err.length >= MAX_CAPTURE,
            )
        }
        outReader.join(2_000)
        errReader.join(2_000)
        return ExecResult(
            exitCode = proc.exitValue(),
            stdout = out.toString(),
            stderr = err.toString(),
            durationMs = System.currentTimeMillis() - startedAt,
            truncated = out.length >= MAX_CAPTURE || err.length >= MAX_CAPTURE,
        )
    }

    private fun appendCapped(sb: StringBuilder, text: String) {
        if (sb.length >= MAX_CAPTURE) return
        sb.append(text, 0, minOf(text.length, MAX_CAPTURE - sb.length))
    }
}

package dev.pocketrun.license

import net.i2p.crypto.eddsa.EdDSAPrivateKey
import net.i2p.crypto.eddsa.EdDSAPublicKey
import net.i2p.crypto.eddsa.EdDSASecurityProvider
import net.i2p.crypto.eddsa.spec.EdDSANamedCurveTable
import net.i2p.crypto.eddsa.spec.EdDSAPrivateKeySpec
import net.i2p.crypto.eddsa.spec.EdDSAPublicKeySpec
import java.security.KeyFactory
import java.security.PrivateKey
import java.security.PublicKey
import java.security.Signature

/**
 * Pure-Java Ed25519. Android only gained a platform Ed25519 provider in API 33,
 * so the app carries its own implementation and behaves the same on every
 * supported device. The signing tool uses the same library.
 */
internal object Ed25519 {
    private const val SIGNATURE_ALGORITHM = "NONEwithEdDSA"
    private val provider = EdDSASecurityProvider()
    private val spec = EdDSANamedCurveTable.getByName("Ed25519")

    fun publicKeyFromRaw(encoded: ByteArray): PublicKey = KeyFactory
        .getInstance("EdDSA", provider)
        .generatePublic(EdDSAPublicKeySpec(encoded, spec))

    /**
     * The 32 raw key bytes. [java.security.PublicKey.getEncoded] would give the
     * 44-byte X.509 SubjectPublicKeyInfo, which is not what gets embedded in the
     * app and not what [publicKeyFromRaw] accepts.
     */
    fun encodePublicKey(publicKey: PublicKey): ByteArray = (publicKey as EdDSAPublicKey).abyte

    fun publicKeyOf(privateKey: PrivateKey): PublicKey = KeyFactory
        .getInstance("EdDSA", provider)
        .generatePublic(EdDSAPublicKeySpec((privateKey as EdDSAPrivateKey).a, spec))

    /** Derives the matching public key from a 32-byte seed. Used by tests. */
    fun publicKeyFromSeed(seed: ByteArray): PublicKey {
        require(seed.size == 32) { "Ed25519 seed must be 32 bytes" }
        val privateKey = KeyFactory
            .getInstance("EdDSA", provider)
            .generatePrivate(EdDSAPrivateKeySpec(seed, spec))
        return publicKeyOf(privateKey)
    }

    fun verify(publicKey: PublicKey, message: ByteArray, signature: ByteArray): Boolean = try {
        Signature.getInstance(SIGNATURE_ALGORITHM, provider).run {
            initVerify(publicKey)
            update(message)
            verify(signature)
        }
    } catch (_: Exception) {
        false
    }
}

package dev.pocketrun.license

import java.nio.charset.StandardCharsets
import java.util.Base64

/**
 * Wire format for PocketRun license keys.
 *
 * A key looks like:
 *
 *     PRK1.<base64url(payload)>.<base64url(ed25519-signature)>
 *
 * The payload is a canonical line-based UTF-8 document, not JSON, so that
 * signing is byte-for-byte reproducible:
 *
 *     PRK1
 *     name=Jane Doe
 *     seat=work-laptop
 *     plan=pro
 *     nbf=1750000000
 *     exp=1760000000
 *
 * The signature covers the raw payload bytes. The verifier therefore never has
 * to re-serialize anything: it decodes the payload, verifies the signature over
 * those exact bytes, and only then parses the claims.
 *
 * This file is duplicated in the signing tool at
 * tools/keygen/src/main/kotlin/dev/pocketrun/keygen/LicenseFormat.kt.
 * Both copies are pinned to the same test vector in
 * src/test/java/dev/pocketrun/license/LicenseFormatTest.kt and
 * tools/keygen/src/test/kotlin/dev/pocketrun/keygen/LicenseFormatTest.kt,
 * so a change on one side that breaks the other fails the build.
 */
object LicenseFormat {
    const val PREFIX = "PRK1"
    const val VERSION = "PRK1"

    private const val KEY_SEPARATOR = '.'
    private val WHITESPACE = Regex("\\s+")

    private val encoder: Base64.Encoder = Base64.getUrlEncoder().withoutPadding()
    private val decoder: Base64.Decoder = Base64.getUrlDecoder()

    data class Claims(
        val name: String,
        val seat: String,
        val plan: String,
        val notBefore: Long,
        val expiresAt: Long,
    ) {
        val isTimeLimited: Boolean get() = expiresAt > 0
    }

    fun encodePayload(claims: Claims): String = buildString {
        append(VERSION).append('\n')
        append("name=").append(escape(claims.name)).append('\n')
        append("seat=").append(escape(claims.seat)).append('\n')
        append("plan=").append(escape(claims.plan)).append('\n')
        append("nbf=").append(claims.notBefore).append('\n')
        append("exp=").append(claims.expiresAt).append('\n')
    }

    fun decodePayload(payload: String): Claims {
        val lines = payload.split('\n')
        require(lines.isNotEmpty() && lines[0] == VERSION) {
            "unsupported license payload version"
        }
        val fields = HashMap<String, String>()
        for (line in lines.drop(1)) {
            if (line.isEmpty()) continue
            val eq = line.indexOf('=')
            require(eq > 0) { "malformed license field: $line" }
            fields[line.substring(0, eq)] = unescape(line.substring(eq + 1))
        }
        return Claims(
            name = fields["name"].orEmpty(),
            seat = fields["seat"].orEmpty(),
            plan = fields["plan"] ?: "trial",
            notBefore = fields["nbf"]?.toLongOrNull() ?: 0L,
            expiresAt = fields["exp"]?.toLongOrNull() ?: 0L,
        )
    }

    fun assemble(payload: String, signature: ByteArray): String {
        val body = encoder.encodeToString(payload.toByteArray(StandardCharsets.UTF_8))
        return PREFIX + KEY_SEPARATOR + body + KEY_SEPARATOR + encoder.encodeToString(signature)
    }

    /** Splits a key into its payload text and signature bytes. */
    fun split(key: String): Pair<String, ByteArray> {
        val clean = normalize(key)
        require(clean.startsWith("$PREFIX$KEY_SEPARATOR")) { "not a PocketRun license key" }
        val rest = clean.removePrefix("$PREFIX$KEY_SEPARATOR")
        val parts = rest.split(KEY_SEPARATOR)
        require(parts.size == 2 && parts.all { it.isNotEmpty() }) { "truncated license key" }
        val payload = String(decoder.decode(parts[0]), StandardCharsets.UTF_8)
        return payload to decoder.decode(parts[1])
    }

    /** Users paste keys with spaces and line breaks; the signature is over the exact bytes. */
    fun normalize(key: String): String = key.replace(WHITESPACE, "")

    fun toDisplayBlocks(key: String, blockSize: Int = 8): String =
        normalize(key).chunked(blockSize).joinToString(" ")

    private fun escape(value: String): String =
        value.replace("\\", "\\\\").replace("\n", "\\n").replace("\r", "\\r")

    private fun unescape(value: String): String {
        val out = StringBuilder(value.length)
        var i = 0
        while (i < value.length) {
            val c = value[i]
            if (c == '\\' && i + 1 < value.length) {
                when (value[i + 1]) {
                    'n' -> out.append('\n')
                    'r' -> out.append('\r')
                    '\\' -> out.append('\\')
                    else -> out.append(c).append(value[i + 1])
                }
                i += 2
            } else {
                out.append(c)
                i++
            }
        }
        return out.toString()
    }
}

package dev.pocketrun.license

import android.content.Context
import android.content.SharedPreferences
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Holds the activated key and exposes it as observable state. The key is
 * re-verified on every launch and whenever the user pastes a new one; nothing is
 * cached as "already validated".
 *
 * [sharedKey] is the key the build itself carries: it is tried first, so a
 * published release works for everyone without anyone pasting anything. The
 * activation screen is still there for a key of one's own, and one that verifies
 * is stored and used instead of the shared one.
 *
 * Verification uses [MonotonicClock], so turning the device clock back cannot
 * bring an expired key back to life.
 */
class LicenseManager(
    context: Context,
    private val publicKey: String,
    private val sharedKey: String = "",
    private val clock: MonotonicClock = MonotonicClock.forContext(context),
) {
    private val prefs: SharedPreferences =
        context.applicationContext.getSharedPreferences("license", Context.MODE_PRIVATE)

    private val _state = MutableStateFlow(evaluate())
    val state: StateFlow<LicenseState> = _state.asStateFlow()

    sealed interface LicenseState {
        data object NeedsActivation : LicenseState
        data class Active(
            val claims: LicenseFormat.Claims,
            val fingerprint: String,
            val daysRemaining: Long?,
            val isShared: Boolean = false,
        ) : LicenseState {
            val canUseAgent: Boolean get() = claims.plan in AGENT_PLANS
        }

        data class Rejected(val message: String) : LicenseState
    }

    /** Accepts a pasted key. Returns true when it verified. */
    fun activate(rawKey: String): Boolean {
        val key = LicenseFormat.normalize(rawKey)
        if (key.isEmpty()) {
            _state.value = LicenseState.Rejected("Enter a license key.")
            return false
        }
        return when (val outcome = LicenseVerifier.verify(key, publicKey, clock.now())) {
            is LicenseVerifier.Outcome.Valid -> {
                prefs.edit().putString(KEY, key).apply()
                _state.value = outcome.toActive(shared = false)
                true
            }

            is LicenseVerifier.Outcome.Expired -> {
                _state.value = LicenseState.Rejected("This license expired.")
                false
            }

            is LicenseVerifier.Outcome.NotYetValid -> {
                _state.value = LicenseState.Rejected("This license is not valid yet.")
                false
            }

            is LicenseVerifier.Outcome.Rejected -> {
                _state.value = LicenseState.Rejected(outcome.reason)
                false
            }
        }
    }

    fun forget() {
        prefs.edit().remove(KEY).apply()
        _state.value = sharedState()
    }

    private fun evaluate(): LicenseState {
        val stored = prefs.getString(KEY, null)
        if (stored.isNullOrBlank()) return sharedState()
        return when (val outcome = LicenseVerifier.verify(LicenseFormat.normalize(stored), publicKey, clock.now())) {
            is LicenseVerifier.Outcome.Valid -> outcome.toActive(shared = false)

            is LicenseVerifier.Outcome.Expired ->
                LicenseState.Rejected(
                    "This license expired on " +
                        java.time.Instant.ofEpochSecond(outcome.claims.expiresAt) + ".",
                )

            is LicenseVerifier.Outcome.NotYetValid ->
                LicenseState.Rejected("This license is not valid yet.")

            is LicenseVerifier.Outcome.Rejected -> LicenseState.Rejected(outcome.reason)
        }
    }

    /**
     * The key the build carries. A build whose shared key does not match its own
     * public key is broken, and that must not lock the user out of the activation
     * screen - so an unusable shared key is simply not used.
     */
    private fun sharedState(): LicenseState {
        val key = LicenseFormat.normalize(sharedKey)
        if (key.isEmpty()) return LicenseState.NeedsActivation
        val outcome = LicenseVerifier.verify(key, publicKey, clock.now())
        return if (outcome is LicenseVerifier.Outcome.Valid) {
            outcome.toActive(shared = true)
        } else {
            LicenseState.NeedsActivation
        }
    }

    private fun LicenseVerifier.Outcome.Valid.toActive(shared: Boolean): LicenseState.Active = LicenseState.Active(
        claims = claims,
        fingerprint = keyFingerprint,
        daysRemaining = LicenseVerifier.daysRemaining(claims, clock.now()),
        isShared = shared,
    )

    companion object {
        private const val KEY = "key"
        private val AGENT_PLANS = setOf("pro", "team", "lifetime")
    }
}

package dev.pocketrun.license

import java.nio.charset.StandardCharsets
import java.util.Base64

/**
 * Offline license check. Everything here is a pure function of the key text and
 * the clock, which is what makes it testable on the JVM without a device.
 *
 * There is no server and no device fingerprint: a key that verifies is valid
 * everywhere. Revocation is therefore impossible by design; a revoked key simply
 * stops working once the build that embeds a newer public key ships.
 */
object LicenseVerifier {

    sealed interface Outcome {
        data class Valid(
            val claims: LicenseFormat.Claims,
            val keyFingerprint: String,
        ) : Outcome

        /** The key parsed and the signature is good, but the clock says no. */
        data class Expired(val claims: LicenseFormat.Claims) : Outcome

        data class NotYetValid(val claims: LicenseFormat.Claims) : Outcome

        /** The key is not a PocketRun key, or the signature does not match. */
        data class Rejected(val reason: String) : Outcome
    }

    data class License(
        val key: String,
        val claims: LicenseFormat.Claims,
        val fingerprint: String,
    )

    fun verify(key: String, publicKeyBase64: String, nowEpochSeconds: Long): Outcome {
        if (publicKeyBase64.isBlank() || publicKeyBase64.startsWith("DEMO")) {
            return Outcome.Rejected(
                "This build has no license public key baked in. Put the key from " +
                    "tools/keygen genkey into android/license.pubkey and rebuild.",
            )
        }

        val (payload, signature) = try {
            LicenseFormat.split(key)
        } catch (e: IllegalArgumentException) {
            return Outcome.Rejected(e.message ?: "malformed key")
        }

        val publicKey = try {
            Ed25519.publicKeyFromRaw(Base64.getUrlDecoder().decode(publicKeyBase64.trim()))
        } catch (_: Exception) {
            return Outcome.Rejected("embedded public key is corrupt")
        }

        val valid = Ed25519.verify(
            publicKey,
            payload.toByteArray(StandardCharsets.UTF_8),
            signature,
        )
        if (!valid) {
            return Outcome.Rejected("signature does not match this build")
        }

        val claims = try {
            LicenseFormat.decodePayload(payload)
        } catch (e: IllegalArgumentException) {
            return Outcome.Rejected(e.message ?: "unreadable claims")
        }

        return when {
            claims.notBefore > nowEpochSeconds ->
                Outcome.NotYetValid(claims)
            claims.isTimeLimited && claims.expiresAt <= nowEpochSeconds ->
                Outcome.Expired(claims)
            else -> Outcome.Valid(claims, fingerprint(signature))
        }
    }

    /** Short stable id for the key, so the UI can show "this device is seat X". */
    fun fingerprint(signature: ByteArray): String {
        val digest = java.security.MessageDigest.getInstance("SHA-256").digest(signature)
        return digest.take(6).joinToString("") { "%02x".format(it) }
    }

    fun daysRemaining(claims: LicenseFormat.Claims, nowEpochSeconds: Long): Long? {
        if (!claims.isTimeLimited) return null
        return ((claims.expiresAt - nowEpochSeconds) / 86_400L).coerceAtLeast(0)
    }
}

package dev.pocketrun.license

import android.content.Context
import android.os.SystemClock

/**
 * A clock that cannot be moved back.
 *
 * A license is only as good as the time it is checked against: `nbf` and `exp`
 * are signed, but both are compared to the device clock, and that clock belongs
 * to whoever holds the device. Moving it back one year re-activates an expired
 * key, for free, forever.
 *
 * The fix is to remember the highest time the app has ever seen and to keep
 * moving that floor forward with a source the user cannot touch:
 *
 * * the wall clock, when it is at or above the floor;
 * * `SystemClock.elapsedRealtime()` — milliseconds since boot, which only ever
 *   counts up and is not settable — added to the floor, so a reboot cannot
 *   rewind it either.
 *
 * What remains possible is wiping the app's data, which also erases the key.
 * That is the honest limit of an offline scheme with no server.
 */
class MonotonicClock(
    private val wallClock: () -> Long = { System.currentTimeMillis() / 1000 },
    private val uptimeMillis: () -> Long = { SystemClock.elapsedRealtime() },
    private val store: Store,
) {

    interface Store {
        /** The remembered floor and the uptime at the moment it was written. */
        fun read(): Saved?

        fun write(saved: Saved)
    }

    data class Saved(val epochSeconds: Long, val uptimeMillis: Long)

    /**
     * The time to verify a license against. Never below anything this app has
     * already observed, and never below the floor advanced by the boot clock.
     */
    fun now(): Long {
        val wall = wallClock()
        val uptime = uptimeMillis()
        val saved = store.read()
        val floor = when {
            saved == null -> wall
            // A reboot drops elapsedRealtime to zero; the wall clock carries it
            // across, and the saved floor is still the hard minimum.
            uptime >= saved.uptimeMillis ->
                maxOf(saved.epochSeconds, saved.epochSeconds + (uptime - saved.uptimeMillis) / 1000)

            else -> saved.epochSeconds
        }
        val result = maxOf(wall, floor)
        if (saved == null || result > saved.epochSeconds) {
            store.write(Saved(result, uptime))
        }
        return result
    }

    companion object {
        private const val PREFS = "license-clock"
        private const val KEY_EPOCH = "floor_epoch"
        private const val KEY_UPTIME = "floor_uptime"

        /** The clock backed by SharedPreferences in [context]. */
        fun forContext(context: Context): MonotonicClock = MonotonicClock(
            store = context.applicationContext.preferences(),
        )

        /** A clock that remembers nothing — for tests and for a fresh install. */
        fun inMemory(): MonotonicClock = MonotonicClock(store = MemoryStore(null))

        private fun Context.preferences() = object : Store {
            private val prefs get() = getSharedPreferences(PREFS, Context.MODE_PRIVATE)

            override fun read(): Saved? {
                val epoch = prefs.getLong(KEY_EPOCH, -1)
                if (epoch < 0) return null
                return Saved(epoch, prefs.getLong(KEY_UPTIME, 0))
            }

            override fun write(saved: Saved) {
                prefs.edit()
                    .putLong(KEY_EPOCH, saved.epochSeconds)
                    .putLong(KEY_UPTIME, saved.uptimeMillis)
                    .apply()
            }
        }

        private class MemoryStore(var saved: Saved?) : Store {
            override fun read(): Saved? = saved
            override fun write(saved: Saved) {
                this.saved = saved
            }
        }
    }
}

