package dev.pocketrun.runtime.npm

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.io.ByteArrayOutputStream
import java.io.File
import java.util.zip.GZIPOutputStream

class TarReaderTest {

    @get:Rule
    val tmp = TemporaryFolder()

    /** Tiny ustar writer so the test does not depend on a system `tar`. */
    private class TarWriter {
        private val out = ByteArrayOutputStream()

        fun file(name: String, content: ByteArray) {
            header(name, content.size.toLong(), '0')
            out.write(content)
            pad(content.size.toLong())
        }

        fun dir(name: String) = header(name, 0, '5')

        private fun header(name: String, size: Long, type: Char) {
            val h = ByteArray(512)
            fun put(offset: Int, s: String, len: Int) {
                val b = s.toByteArray(Charsets.UTF_8)
                System.arraycopy(b, 0, h, offset, minOf(b.size, len))
            }
            put(0, name, 100)
            put(100, "000644", 8)   // mode
            put(108, "000000", 8)   // uid
            put(116, "000000", 8)   // gid
            put(124, java.lang.Long.toOctalString(size).padStart(11, '0') + "\u0000", 12)
            put(136, "00000000000", 12) // mtime
            put(148, "        ", 8)     // checksum placeholder
            h[156] = type.code.toByte()
            put(257, "ustar\u000000", 8)
            // checksum: spaces treated as NUL
            var sum = 0
            for (i in 0 until 512) sum += (h[i].toInt() and 0xFF)
            put(148, "%06o\u0000 ".format(sum), 8)
            out.write(h)
        }

        private fun pad(size: Long) {
            val pad = ((512 - (size % 512)) % 512).toInt()
            repeat(pad) { out.write(0) }
        }

        fun toTgz(file: File) {
            GZIPOutputStream(file.outputStream()).use { gz -> gz.write(out.toByteArray()) }
        }
    }

    @Test
    fun extractsPackagePrefix() {
        val writer = TarWriter().apply {
            dir("package/")
            dir("package/lib/")
            file("package/package.json", """{"name":"fake","version":"1.0.0","bin":"cli.js"}""".toByteArray())
            file("package/lib/util.js", "module.exports = function(){ return 42; };".toByteArray())
            file("package/cli.js", "console.log('hi');".toByteArray())
        }
        val tgz = tmp.newFile("fake-1.0.0.tgz")
        writer.toTgz(tgz)

        val dest = tmp.newFolder("out")
        TarReader.extract(tgz, dest, "package/")

        assertEquals("fake", File(dest, "package.json").readText().let { org.json.JSONObject(it).getString("name") })
        assertEquals("console.log('hi');", File(dest, "cli.js").readText())
        assertEquals("module.exports = function(){ return 42; };", File(dest, "lib/util.js").readText())
    }

    @Test
    fun skipsEntriesOutsidePrefix() {
        val writer = TarWriter().apply {
            file("package/ok.txt", "ok".toByteArray())
            file("/etc/evil.txt", "evil".toByteArray()) // absolute name — must be refused
            file("package/../evil.txt", "evil".toByteArray()) // traversal — must be refused
        }
        val tgz = tmp.newFile("evil.tgz")
        writer.toTgz(tgz)

        val dest = tmp.newFolder("out")
        TarReader.extract(tgz, dest, "package/")

        assertTrue(File(dest, "ok.txt").isFile)
        assertFalse(File(dest, "../evil.txt").exists())
        // nothing escaped the destination dir
        assertFalse(File(tmp.root, "evil.txt").exists())
    }

    @Test
    fun longNamesWithUstarPrefix() {
        // ustar splits long paths at a '/' boundary: prefix (≤155 bytes) in the
        // prefix field, the rest (≤100 bytes) in the name field; the reader
        // rejoins them with '/'.
        val prefix = "package/" + "a".repeat(100) // 108 bytes
        val name = "deep/" + "b".repeat(90) + ".txt" // 99 bytes
        val fullName = "$prefix/$name"
        assertTrue(prefix.toByteArray(Charsets.UTF_8).size <= 155)
        assertTrue(name.toByteArray(Charsets.UTF_8).size <= 100)

        val out = ByteArrayOutputStream()
        val h = ByteArray(512)
        fun put(offset: Int, s: String, len: Int) {
            val b = s.toByteArray(Charsets.UTF_8)
            System.arraycopy(b, 0, h, offset, minOf(b.size, len))
        }
        put(0, name, 100)
        put(124, "%011o\u0000".format(5L), 12)
        h[156] = '0'.code.toByte()
        put(257, "ustar\u000000", 8)
        put(345, prefix, 155)
        var sum = 0
        for (i in 0 until 512) sum += (h[i].toInt() and 0xFF)
        put(148, "%06o\u0000 ".format(sum), 8)
        out.write(h)
        out.write("hello".toByteArray())
        out.write(ByteArray((512 - 5 % 512) % 512))
        out.write(ByteArray(1024)) // end-of-archive
        val tgz = tmp.newFile("long.tgz")
        GZIPOutputStream(tgz.outputStream()).use { it.write(out.toByteArray()) }

        val dest = tmp.newFolder("out")
        TarReader.extract(tgz, dest, "package/")
        val extracted = File(dest, fullName.removePrefix("package/"))
        assertTrue("expected ${extracted.absolutePath}", extracted.isFile)
        assertEquals("hello", extracted.readText())
    }
}

package dev.pocketrun.update

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/** The updater's arithmetic and its reading of a GitHub release, without a device. */
class AppUpdateTest {

    private val release = """
        {
          "tag_name": "v1.5.0",
          "name": "PocketRun v1.5.0",
          "body": "песочница и обновления",
          "assets": [
            { "name": "PocketRun-v1.5.0-debug.apk", "size": 35,
              "browser_download_url": "https://example.test/debug.apk" },
            { "name": "PocketRun-v1.5.0-release.apk", "size": 19,
              "browser_download_url": "https://example.test/release.apk" }
          ]
        }
    """.trimIndent()

    @Test
    fun `the release apk is the one to install`() {
        val info = AppUpdate.parse(release)
        assertEquals("v1.5.0", info.tag)
        assertEquals("1.5.0", info.version)
        assertEquals("PocketRun-v1.5.0-release.apk", info.asset.name)
        assertEquals("https://example.test/release.apk", info.asset.url)
        assertEquals(19L, info.asset.size)
    }

    @Test
    fun `a differently named apk is still installable`() {
        val odd = release.replace("PocketRun-v1.5.0-release.apk", "pocketrun.apk")
        assertEquals("pocketrun.apk", AppUpdate.parse(odd).asset.name)
    }

    @Test(expected = AppUpdate.ParseException::class)
    fun `a release with only a debug apk is refused`() {
        AppUpdate.parse("""
            {"tag_name":"v1.5.0","assets":[
              {"name":"PocketRun-v1.5.0-debug.apk","size":35,"browser_download_url":"https://x/d.apk"}]}
        """.trimIndent())
    }

    @Test(expected = AppUpdate.ParseException::class)
    fun `a release without an apk is refused`() {
        AppUpdate.parse("""{"tag_name":"v1.5.0","assets":[]}""")
    }

    @Test(expected = AppUpdate.ParseException::class)
    fun `a draft is not an update`() {
        AppUpdate.parse("""{"tag_name":"v1.5.0","draft":true,"assets":[]}""")
    }

    @Test
    fun `the version is read out of the tag and the build suffix`() {
        assertEquals("1.5.0", AppUpdate.version("v1.5.0"))
        assertEquals("1.5.0", AppUpdate.version("1.5.0-debug"))
        assertEquals("1.5.1", AppUpdate.version("V1.5.1+build7"))
    }

    @Test
    fun `only a strictly newer version is an update`() {
        assertTrue(AppUpdate.isNewer("1.5.0", "1.4.2"))
        assertTrue(AppUpdate.isNewer("1.10.0", "1.9.9"))
        assertTrue(AppUpdate.isNewer("2.0", "1.99.99"))
        assertFalse(AppUpdate.isNewer("1.4.2", "1.4.2"))
        assertFalse(AppUpdate.isNewer("1.4.2", "1.5.0"))
        assertFalse(AppUpdate.isNewer("1.5", "1.5.0"))
    }

    @Test
    fun `a prerelease does not outrank its release`() {
        assertFalse(AppUpdate.isNewer("1.5.0-rc1", "1.5.0"))
    }
}

package dev.pocketrun.runtime.npm

import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.ExecRequest
import dev.pocketrun.runtime.RuntimeKind
import dev.pocketrun.runtime.js.JsRuntime
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.io.File

/**
 * npm/npx pieces that need no network: spec parsing, bin resolution and the
 * run path over an already-installed package (the same path a cached install
 * takes after the first download).
 */
class NpxRuntimeTest {

    @get:Rule
    val tmp = TemporaryFolder()

    private fun bootSource(): String {
        val candidates = listOf(
            File("src/main/assets/node/boot.js"),
            File("app/src/main/assets/node/boot.js"),
        )
        return candidates.firstOrNull { it.isFile }?.readText(Charsets.UTF_8)
            ?: error("boot.js not found")
    }

    private fun newNpx(workspace: Workspace): Pair<JsRuntime, NpxRuntime> {
        val js = JsRuntime(bootSource(), workspace, maxRunMs = 30_000)
        return js to NpxRuntime(js, workspace)
    }

    @Test
    fun parseSpecVariants() {
        assertEquals(NpxRuntime.PackageSpec("cowsay", null), NpxRuntime.parseSpec("cowsay"))
        assertEquals(NpxRuntime.PackageSpec("cowsay", "1.6.0"), NpxRuntime.parseSpec("cowsay@1.6.0"))
        assertEquals(NpxRuntime.PackageSpec("cowsay", "^1.6"), NpxRuntime.parseSpec("cowsay@^1.6"))
        assertEquals(NpxRuntime.PackageSpec("@scope/pkg", null), NpxRuntime.parseSpec("@scope/pkg"))
        assertEquals(NpxRuntime.PackageSpec("@scope/pkg", "2.1.0"), NpxRuntime.parseSpec("@scope/pkg@2.1.0"))
        assertNull(NpxRuntime.parseSpec("not a package!"))
        assertNull(NpxRuntime.parseSpec(""))
        assertNull(NpxRuntime.parseSpec("@broken"))
    }

    @Test
    fun parseCommandLineWithArgs() {
        val (spec, args) = NpxRuntime.parseCommandLine("""cowsay -f tux 'hello мир'""")!!
        assertEquals("cowsay", spec.name)
        assertNull(spec.version)
        assertEquals(listOf("-f", "tux", "hello мир"), args)

        val (spec2, args2) = NpxRuntime.parseCommandLine("semver@7.6.0 -h")!!
        assertEquals("semver", spec2.name)
        assertEquals("7.6.0", spec2.version)
        assertEquals(listOf("-h"), args2)
    }

    @Test
    fun resolveBinPrefersNameMatchThenFirst() {
        val workspace = Workspace.at(tmp.newFolder())
        val (_, npx) = newNpx(workspace)
        val pkg = File(workspace.root, "packages/tool").apply { mkdirs() }
        File(pkg, "package.json").writeText(
            """{"name":"@scope/tool","bin":{"other":"o.js","tool":"t.js"}}""",
        )
        File(pkg, "t.js").writeText("// t")
        File(pkg, "o.js").writeText("// o")

        val bin = npx.resolveBin(pkg, "@scope/tool")
        assertNotNull(bin)
        assertEquals("t.js", bin!!.name)
    }

    @Test
    fun runsInstalledPackageBinWithArgs() {
        val workspace = Workspace.at(tmp.newFolder())
        val (js, npx) = newNpx(workspace)

        // A fake installed package: main + bin + a nested dep to prove the walk.
        val pkg = File(workspace.root, "packages/greeter").apply { mkdirs() }
        File(pkg, "package.json").writeText(
            """{"name":"greeter","version":"1.0.0","bin":"bin/greet.js"}""",
        )
        File(pkg, "bin").mkdirs()
        File(pkg, "bin/greet.js").writeText(
            """
            var greet = require('../lib/greet.js');
            console.log(greet(process.argv.slice(2).join(' ')));
            """.trimIndent(),
        )
        File(pkg, "lib").mkdirs()
        File(pkg, "lib/greet.js").writeText(
            "module.exports = function (name) { return 'Привет, ' + (name || 'мир') + '!'; };",
        )

        val result = npx.executeSync(
            ExecRequest(
                RuntimeKind.NPX,
                "greeter",
                args = listOf("PocketRun"),
                cwd = workspace.root,
            ),
            20_000,
        )
        assertEquals("stdout: ${result.stdout}\nstderr: ${result.stderr}", 0, result.exitCode)
        assertTrue("stdout: ${result.stdout}", result.stdout.contains("Привет, PocketRun!"))
    }

    @Test
    fun installedPackagesList() {
        val workspace = Workspace.at(tmp.newFolder())
        val (_, npx) = newNpx(workspace)
        val pkg = File(workspace.root, "packages/alpha").apply { mkdirs() }
        File(pkg, "package.json").writeText("""{"name":"alpha","version":"0.1.2"}""")

        val list = npx.installedPackages()
        assertEquals(1, list.size)
        assertEquals("alpha" to "0.1.2", list[0])
    }

    @Test
    fun chooseVersionPicksDistTagExactRangeMax() {
        val meta = org.json.JSONObject(
            """
            {
              "dist-tags": {"latest": "2.0.0", "beta": "3.0.0-beta.1"},
              "versions": {
                "1.0.0": {}, "1.2.3": {}, "1.10.0": {}, "2.0.0": {},
                "3.0.0-beta.1": {}, "9.9.9-pre": {}
              }
            }
            """.trimIndent(),
        )
        val workspace = Workspace.at(tmp.newFolder())
        val (_, npx) = newNpx(workspace)
        assertEquals("2.0.0", npx.chooseVersion(meta, null))
        assertEquals("2.0.0", npx.chooseVersion(meta, "latest"))
        assertEquals("1.10.0", npx.chooseVersion(meta, "^1.0.0")) // numeric ordering, not lexicographic
        assertEquals("1.2.3", npx.chooseVersion(meta, "1.2.3"))
        assertEquals("3.0.0-beta.1", npx.chooseVersion(meta, "beta"))
        assertEquals("2.0.0", npx.chooseVersion(meta, ">=1.2.3 <3.0.0"))
        assertNull(npx.chooseVersion(meta, "^5.0.0"))
    }
}

