package dev.pocketrun.core

import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class FileOpsTest {

    private fun dir(): File = File.createTempFile("pocketrun-ops", "").let {
        it.delete()
        it.mkdirs()
        it
    }

    @Test
    fun namesThatWouldEscapeTheProjectAreRejected() {
        assertNull(FileOps.safeName("../outside"))
        assertNull(FileOps.safeName("a/b"))
        assertNull(FileOps.safeName(".."))
        assertNull(FileOps.safeName("  "))
        assertNull(FileOps.safeName("x".repeat(200)))
        assertEquals("notes.txt", FileOps.safeName(" notes.txt "))
    }

    @Test
    fun aTakenNameGetsACounter() {
        val root = dir()
        File(root, "main.py").writeText("a")
        assertEquals("main (2).py", FileOps.uniqueName(root, "main.py").name)
        assertEquals("new.txt", FileOps.uniqueName(root, "new.txt").name)
    }

    @Test
    fun createRenameMoveDelete() {
        val root = dir()
        val a = FileOps.createFile(root, "a.txt", "hello")
        assertNotNull(a)
        assertEquals("hello", a!!.readText())

        val b = FileOps.rename(a, "b.txt")
        assertEquals("b.txt", b?.name)
        assertFalse(a.exists())

        val sub = FileOps.createDir(root, "sub")
        assertNotNull(sub)
        val moved = FileOps.move(b!!, sub!!)
        assertEquals(File(sub, "b.txt").absolutePath, moved?.absolutePath)
        assertTrue(moved!!.isFile)

        assertTrue(FileOps.delete(moved))
        assertFalse(moved.exists())
    }

    @Test
    fun renameDoesNotClobberAnExistingFile() {
        val root = dir()
        val keep = FileOps.createFile(root, "keep.txt", "keep")!!
        val other = FileOps.createFile(root, "other.txt", "other")!!
        val renamed = FileOps.rename(other, "keep.txt")
        assertEquals("keep (2).txt", renamed?.name)
        assertEquals("keep", keep.readText())
    }

    @Test
    fun aFolderCannotBeMovedIntoItself() {
        val root = dir()
        val sub = FileOps.createDir(root, "sub")!!
        val inner = FileOps.createDir(sub, "inner")!!
        assertNull(FileOps.move(sub, inner))
    }
}

class FileTextTest {

    private fun file(bytes: ByteArray): File = File.createTempFile("pocketrun-text", "").also {
        it.writeBytes(bytes)
    }

    @Test
    fun binaryFilesAreNotReadAsText() {
        val png = file(byteArrayOf(0x89.toByte(), 0x50, 0x4E, 0x47, 0, 0, 0, 13))
        assertTrue(FileText.looksBinary(png))
        assertNull(FileText.read(png))
    }

    @Test
    fun cyrillicSurvivesTheRoundTrip() {
        val f = file("Привет, PocketRun!\n第二行".toByteArray())
        assertFalse(FileText.looksBinary(f))
        assertEquals("Привет, PocketRun!\n第二行", FileText.read(f))
    }

    @Test
    fun humanSizesReadLikeAPersonWouldSayThem() {
        assertEquals("512 Б", FileText.human(512))
        assertEquals("1,0 КБ", FileText.human(1024).replace('.', ','))
        assertEquals("1,4 МБ", FileText.human(1_500_000).replace('.', ','))
    }
}

class ContentSearchTest {

    private fun project(): File {
        val root = File.createTempFile("pocketrun-search", "").let {
            it.delete()
            it.mkdirs()
            it
        }
        File(root, "a.py").writeText("def main():\n    return 42\n")
        File(root, "sub").mkdirs()
        File(root, "sub/b.txt").writeText("nothing here\n")
        File(root, "sub/c.py").writeText("print('main')\n")
        File(root, "bin.dat").writeBytes(byteArrayOf(0, 1, 2))
        File(root, "node_modules").mkdirs()
        File(root, "node_modules/d.py").writeText("main\n")
        return root
    }

    @Test
    fun findsHitsWithLineNumbersInNestedFiles() {
        val hits = ContentSearch.search(project(), "main")
        assertEquals(2, hits.size)
        val inA = hits.first { it.file.name == "a.py" }
        assertEquals(1, inA.line)
        val inC = hits.first { it.file.name == "c.py" }
        assertEquals(1, inC.line)
    }

    @Test
    fun caseSensitiveAndRegexModes() {
        assertTrue(ContentSearch.search(project(), "NOTHING", caseSensitive = true).isEmpty())
        val regex = ContentSearch.search(project(), "def \\w+\\(\\):", regex = true)
        assertEquals(1, regex.size)
    }

    @Test
    fun anImpossibleRegexIsAnEmptyResultNotACrash() {
        assertTrue(ContentSearch.search(project(), "[unclosed", regex = true).isEmpty())
    }

    @Test
    fun anEmptyQueryFindsNothing() {
        assertTrue(ContentSearch.search(project(), "   ").isEmpty())
    }
}

class FileHistoryTest {

    @Test
    fun snapshotRestoreRoundTrip() {
        val project = File.createTempFile("pocketrun-hist", "").let {
            it.delete()
            it.mkdirs()
            it
        }
        val history = FileHistory(File(project, ".history"))
        val file = File(project, "notes.txt")
        file.writeText("original")

        val saved = history.snapshot(file, project)
        assertNotNull(saved)
        file.writeText("what the agent wrote")
        assertEquals("what the agent wrote", file.readText())

        assertTrue(history.restore(saved!!, file, project))
        assertEquals("original", file.readText())
        // Restoring is itself undoable: the overwritten text is kept too.
        assertTrue(history.versionsOf(file, project).any {
            FileText.read(it.file)?.contains("what the agent wrote") == true
        })
    }

    @Test
    fun versionsOfAnUntouchedFileAreEmpty() {
        val project = File.createTempFile("pocketrun-hist2", "").let {
            it.delete()
            it.mkdirs()
            it
        }
        val history = FileHistory(File(project, ".history"))
        assertTrue(history.versionsOf(File(project, "nope.txt"), project).isEmpty())
    }

    @Test
    fun filesInSubfoldersDoNotShareASlot() {
        val project = File.createTempFile("pocketrun-hist3", "").let {
            it.delete()
            it.mkdirs()
            it
        }
        val history = FileHistory(File(project, ".history"))
        val a = File(project, "a/b.txt").apply { parentFile.mkdirs(); writeText("1") }
        val b = File(project, "b.txt").apply { writeText("2") }
        history.snapshot(a, project)
        history.snapshot(b, project)
        assertEquals(1, history.versionsOf(a, project).size)
        assertEquals(1, history.versionsOf(b, project).size)
        assertEquals("1", FileText.read(history.versionsOf(a, project).first().file))
    }
}

package dev.pocketrun.core

import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class FileTreeTest {

    private fun tree(): File {
        val root = File.createTempFile("pocketrun-tree", "").let {
            it.delete()
            it.mkdirs()
            it
        }
        File(root, "src/main").mkdirs()
        File(root, "src/assets").mkdirs()
        File(root, "src/main.py").writeText("print(1)")
        File(root, "README.md").writeText("# hi")
        File(root, "photo.jpg").writeBytes(byteArrayOf(1, 2, 3))
        File(root, "clip.mp4").writeBytes(byteArrayOf(1, 2, 3))
        File(root, "notes.txt").writeText("hi")
        File(root, "app.apk").writeBytes(byteArrayOf(1))
        File(root, ".env").writeText("SECRET=1")
        File(root, "node_modules/left-pad").mkdirs()
        File(root, "node_modules/left-pad/index.js").writeText("x")
        return root
    }

    @Test
    fun classifiesByWhatTheViewerNeeds() {
        val root = tree()
        assertEquals(FileKind.CODE, FileTree.kindOf(File(root, "src/main.py")))
        assertEquals(FileKind.TEXT, FileTree.kindOf(File(root, "README.md")))
        assertEquals(FileKind.TEXT, FileTree.kindOf(File(root, "notes.txt")))
        assertEquals(FileKind.IMAGE, FileTree.kindOf(File(root, "photo.jpg")))
        assertEquals(FileKind.VIDEO, FileTree.kindOf(File(root, "clip.mp4")))
        assertEquals(FileKind.ARCHIVE, FileTree.kindOf(File(root, "app.apk")))
        assertEquals(FileKind.FOLDER, FileTree.kindOf(File(root, "src")))
        assertTrue(FileTree.isTextual(FileKind.CODE))
        assertFalse(FileTree.isTextual(FileKind.IMAGE))
    }

    @Test
    fun foldersComeFirstAndHiddenNoiseIsLeftOut() {
        val root = tree()
        val names = FileTree.build(root, emptySet(), TreeFilter()).map { it.name }
        // Folders first, then names case-insensitively: readme.md sorts after photo.jpg.
        assertEquals(listOf("src", "app.apk", "clip.mp4", "notes.txt", "photo.jpg", "README.md"), names)
    }

    @Test
    fun collapsedFoldersAreNotWalked() {
        val root = tree()
        val collapsed = FileTree.build(root, emptySet(), TreeFilter()).map { it.name }
        assertFalse(collapsed.contains("main.py"))

        val opened = FileTree.build(root, setOf(File(root, "src").absolutePath), TreeFilter())
        assertTrue(opened.any { it.name == "main.py" })
        assertEquals(0, opened.first { it.name == "src" }.depth)
        assertEquals(1, opened.first { it.name == "main.py" }.depth)
    }

    @Test
    fun aSearchRevealsFilesInsideCollapsedFolders() {
        val root = tree()
        val hits = FileTree.build(root, emptySet(), TreeFilter(query = "main.py"))
        // src/ was never expanded, and main.py still shows up - with src above it.
        assertEquals(listOf("src", "main.py"), hits.map { it.name })
    }

    @Test
    fun kindFilterKeepsOnlyThatKind() {
        val root = tree()
        val hits = FileTree.build(root, emptySet(), TreeFilter(kind = FileKind.IMAGE))
        assertEquals(listOf("photo.jpg"), hits.map { it.name })
    }

    @Test
    fun hiddenToggleShowsDotfiles() {
        val root = tree()
        val hidden = FileTree.build(root, emptySet(), TreeFilter(showHidden = true))
        assertTrue(hidden.any { it.name == ".env" })
        assertTrue(hidden.any { it.name == "node_modules" })
    }

    @Test
    fun fingerprintMovesWhenTheAgentWritesAFile() {
        val root = tree()
        val before = FileTree.fingerprint(root)
        assertEquals(before, FileTree.fingerprint(root))
        File(root, "src/new.py").writeText("x")
        assertTrue(FileTree.fingerprint(root) != before)
    }

    @Test
    fun foldersCarryTheirOwnCounts() {
        val root = tree()
        val src = FileTree.build(root, emptySet(), TreeFilter()).first { it.name == "src" }
        assertEquals(2, src.folders)
        assertEquals(1, src.files)
    }
}

package dev.pocketrun.core

import java.io.File
import java.io.IOException
import java.util.concurrent.atomic.AtomicLong

/** One saved copy of a file, newest first when listed. */
data class Version(
    val file: File,
    val stamp: Long,
    val size: Long,
    val project: String,
) {
    val label: String get() = file.name.substringAfter("__", file.name)
}

/**
 * Versions of the files the user cares about, kept beside the projects.
 *
 * The agent edits files without asking first (it does ask, but the user can
 * approve a patch they have not read carefully), and there is no undo anywhere
 * else in the app. So before anything overwrites or deletes a file - a save in
 * the editor, a write from the agent, a delete in the file manager - the old
 * content is copied here, and the file manager offers to put it back.
 *
 * Layout: `.history/<project>/<mangled-relative-path>/<stamp>__<name>`.
 */
class FileHistory(private val root: File) {

    /** Copies the current content aside. Returns the copy, or null when there is
     *  nothing to keep (missing file) or the copy failed. */
    fun snapshot(file: File, projectDir: File): Version? {
        if (!file.isFile) return null
        val dir = dirFor(file, projectDir)
        val target = File(dir, "${stamp()}_${file.name.take(80)}")
        return try {
            file.copyTo(target, overwrite = false)
            version(target, projectDir.name)
        } catch (_: IOException) {
            null
        }
    }

    /** Every saved copy of this file, newest first. */
    fun versionsOf(file: File, projectDir: File): List<Version> {
        val dir = dirFor(file, projectDir)
        val entries = dir.listFiles()?.filter { it.isFile } ?: return emptyList()
        return entries
            .map { version(it, projectDir.name) }
            .sortedByDescending { it.stamp }
    }

    /**
     * Puts a saved copy back. The current content is snapshotted first, so
     * "restore" is itself undoable.
     */
    fun restore(version: Version, target: File, projectDir: File): Boolean {
        if (!version.file.isFile) return false
        if (target.isFile) snapshot(target, projectDir)
        return try {
            target.parentFile?.mkdirs()
            version.file.copyTo(target, overwrite = true)
            true
        } catch (_: IOException) {
            false
        }
    }

    fun deleteVersion(version: Version): Boolean = version.file.delete()

    /** Keeps the newest [keep] copies so the history folder cannot grow forever. */
    fun prune(file: File, projectDir: File, keep: Int = 20) {
        versionsOf(file, projectDir).drop(keep).forEach { it.file.delete() }
    }

    private fun dirFor(file: File, projectDir: File): File =
        File(File(root, FileOps.slug(projectDir.name)), key(file, projectDir)).apply { mkdirs() }

    /** The relative path with separators encoded, so a folder and a file with the
     *  same name can never land in the same history slot. */
    private fun key(file: File, projectDir: File): String {
        val relative = try {
            file.absolutePath.removePrefix(projectDir.absolutePath).trimStart(File.separatorChar)
        } catch (_: IllegalArgumentException) {
            file.name
        }
        val encoded = relative.replace("%", "%25").replace(File.separatorChar, '~')
        return encoded.ifEmpty { file.name }
    }

    private fun version(file: File, project: String): Version = Version(
        file = file,
        stamp = file.name.substringBefore("__").toLongOrNull() ?: 0L,
        size = file.length(),
        project = project,
    )

    private fun stamp(): String = String.format(
        // millisecond << counter: two snapshots in the same millisecond (e.g. a
        // restore() snapshoting the pre-restore content) must not collide, or
        // the copy is silently dropped and "restore is undoable" breaks.
        "%017d", System.currentTimeMillis() * 10_000 + counter.incrementAndGet() % 10_000,
    )

    private val counter = AtomicLong()

    companion object {
        fun under(workspace: Workspace): FileHistory =
            FileHistory(File(workspace.root, ".history"))
    }
}
